INSERT INTO public.quiz_questions (subject, question, options, correct_index, explanation, source, topic)
VALUES
  ('Služební příprava', 'Jak postupuje strážný u hlavního vchodu, odmítne-li vstupující osoba vydat do úschovy mobilní telefon?', '["Osobu do objektu nevpustí a informuje nadřízeného", "Telefon zapíše do Knihy osob a osobu vpustí", "Telefon osobě odebere a vstup jí přesto umožní", "Vpustí ji pod podmínkou trvalého doprovodu příslušníkem"]'::jsonb, 0, 'Strážný dotazem zjišťuje, zda vstupující osoba nemá mobilní komunikační či záznamové zařízení, a takové věci převezme do úschovy. Odmítne-li osoba věc vydat do úschovy, do objektu se nevpustí a informuje se nadřízený. (Právní úprava: § 80 NGŘ č. 33/2019; učební text Strážní služba (Kupec), s. 20–23)', '§ 80 NGŘ č. 33/2019; učební text Strážní služba (Kupec), s. 20–23', 'Strážní služba – hlavní vchod'),
  ('Služební příprava', 'Bez čího souhlasu nesmí strážný u hlavního vchodu propouštět tímto vchodem vězněné osoby?', '["Bez souhlasu inspektora dozorčí služby oddělení výkonu trestu", "Bez souhlasu vrchního inspektora strážní služby", "Bez souhlasu operačního střediska věznice", "Bez souhlasu vedoucího oddělení výkonu trestu"]'::jsonb, 1, 'Mezi zákazy strážného u hlavního vchodu patří propouštět tímto vchodem vězněné osoby bez souhlasu vrchního inspektora strážní služby (VISS). (Právní úprava: § 80 NGŘ č. 33/2019)', '§ 80 NGŘ č. 33/2019', 'Strážní služba – hlavní vchod'),
  ('Penologie', 'Kdo může z bezpečnostních důvodů rozhodnout, že návštěva odsouzeného proběhne v místnosti, kde je návštěvník oddělen přepážkou?', '["Vychovatel odsouzeného", "Dozorový státní zástupce", "Ředitel věznice", "Vrchní dozorce"]'::jsonb, 2, 'Podle § 19 odst. 6 zákona o výkonu trestu může o návštěvě v místnosti s přepážkou z bezpečnostních důvodů rozhodnout ředitel věznice; ředitel může podle § 19 odst. 5 povolit i návštěvu bez zrakové a sluchové kontroly. (Právní úprava: § 19 odst. 6 zákona č. 169/1999 Sb.)', '§ 19 odst. 6 zákona č. 169/1999 Sb.', 'Návštěvy odsouzených'),
  ('Právo', 'Za jaký trestný čin odpovídá ten, kdo se požitím návykové látky přivedl do nepříčetnosti a v ní se dopustil činu jinak trestného?', '["Za přípravu k dotyčnému trestnému činu (§ 20 TZ)", "Za dotyčný čin, ale jako zmenšeně příčetný (§ 27 TZ)", "Za nic, nepříčetnost vylučuje odpovědnost (§ 26 TZ)", "Za samostatný trestný čin opilství podle § 360 TZ"]'::jsonb, 3, 'Nepříčetnosti se nemůže dovolávat ten, kdo se do ní přivedl požitím návykové látky; pokud v tomto stavu spáchá čin jinak trestný, odpovídá za trestný čin opilství podle § 360 TZ. Zmenšená příčetnost (§ 27) se týká podstatně snížených schopností pro duševní poruchu. (Právní úprava: § 26, § 27 a § 360 zákona č. 40/2009 Sb.)', '§ 26, § 27 a § 360 zákona č. 40/2009 Sb.', 'Trestní odpovědnost – nepříčetnost'),
  ('Služební příprava', 'Komu je dozorce oddělení výkonu trestu přímo podřízen?', '["Inspektorovi dozorčí služby oddělení výkonu trestu", "Vrchnímu inspektorovi strážní služby", "Vychovateli oddílu, na kterém koná službu", "Vedoucímu oddělení výkonu trestu a všem jeho zástupcům"]'::jsonb, 0, 'Dozorce oddělení výkonu trestu je přímo podřízen inspektorovi dozorčí služby (IDS) oddělení výkonu trestu. Pokyny vychovatele respektuje jen v oblasti realizace práv a oprávněných zájmů odsouzených. (Právní úprava: § 62 NGŘ č. 02/2022)', '§ 62 NGŘ č. 02/2022', 'Dozorčí služba – ubytovna odsouzených'),
  ('Služební příprava', 'Který příslušník je podle § 7 zákona č. 555/1992 Sb. povinen zakročit i mimo službu?', '["Pouze příslušník zařazený k justiční stráži", "Pouze příslušník plnící úkoly vězeňské stráže", "Pouze příslušník ve vedoucím služebním místě a s kázeňskou pravomocí", "Každý příslušník bez ohledu na zařazení"]'::jsonb, 1, 'Mimo službu je povinen zakročit pouze příslušník plnící úkoly vězeňské stráže, a to páchá-li vězněná osoba trestný čin nebo kázeňský přestupek, jímž je bezprostředně ohrožen život, zdraví nebo majetek. (Právní úprava: § 7 odst. 3 a 4 zákona č. 555/1992 Sb.)', '§ 7 odst. 3 a 4 zákona č. 555/1992 Sb.', 'Povinnost zakročit'),
  ('Penologie', 'Do jaké výše lze odsouzenému uložit kázeňský trest pokuty?', '["Až do výše 500 Kč", "Až do výše 10 000 Kč", "Až do výše 5 000 Kč", "Až do výše 2 000 Kč"]'::jsonb, 2, 'Zákon o výkonu trestu připouští jako kázeňský trest pokutu až do 5 000 Kč; lze uložit jen trest v zákoně uvedený. (Právní úprava: § 46 zákona č. 169/1999 Sb.)', '§ 46 zákona č. 169/1999 Sb.', 'Kázeňské tresty'),
  ('Penologie', 'V jaké lhůtě může odsouzený podat stížnost proti rozhodnutí o kázeňském trestu?', '["Do 15 dnů od oznámení rozhodnutí", "Do 8 dnů od oznámení rozhodnutí", "Ihned při oznámení rozhodnutí", "Do 3 dnů od oznámení rozhodnutí"]'::jsonb, 3, 'Odsouzený má právo podat stížnost do 3 dnů od oznámení rozhodnutí; o stížnosti se rozhodne do 5 pracovních dnů. (Právní úprava: § 52 zákona č. 169/1999 Sb.)', '§ 52 zákona č. 169/1999 Sb.', 'Kázeňské tresty'),
  ('Vězeňská administrativa', 'Co se sepíše, jestliže odsouzený odmítne podepsat zápis o vyřešení kázeňského přestupku domluvou v jednotném záznamovém listu?', '["Sepíše se záznam o kázeňském přestupku", "Zápis podepíšou dva svědci místo něj", "Pouze služební záznam o odmítnutí podpisu", "Nic, domluva platí i bez jeho podpisu"]'::jsonb, 0, 'Postačí-li k nápravě domluva, záznam o kázeňském přestupku se nesepisuje a vyřešení domluvou se zapíše do VIS a do jednotného záznamového listu, který odsouzený podepíše. Odmítne-li podpis, sepíše se záznam o kázeňském přestupku. (Právní úprava: § 17 NGŘ č. 41/2024)', '§ 17 NGŘ č. 41/2024', 'Záznam o kázeňském přestupku'),
  ('Psychologie', 'Která forma agrese je podle učebního textu psychologie v penitenciárním prostředí nejčastější?', '["Nepřímá fyzická agrese ničením zařízení cel", "Přímá aktivní verbální agrese vůči zaměstnanci", "Autoagrese – sebepoškozování protestního rázu a z jiných pohnutek", "Plánovaný instrumentální fyzický útok"]'::jsonb, 1, 'Nejčastější formou je přímá a aktivní verbální agrese – slovní výpady vůči zaměstnanci, vulgarismy, křik a vyhrožování stížnostmi nebo pomstou. Příslušník se nemá nechat strhnout k jejímu opětování. (Právní úprava: učební text Psychologie pro ZOP (Akademie VS ČR, 2023), kapitola Agresivní projevy vězňů vůči zaměstnancům)', 'učební text Psychologie pro ZOP (Akademie VS ČR, 2023), kapitola Agresivní projevy vězňů vůči zaměstnancům', 'Agrese vězňů'),
  ('Služební příprava', 'Kdo podepisuje propustku pro eskortu do zdravotnického zařízení?', '["Ředitel věznice, v jeho nepřítomnosti jeho první zástupce ve službě", "Velitel eskorty, v jeho nepřítomnosti strážný", "Vedoucí oddělení vězeňské stráže, v jeho nepřítomnosti VISS", "Ošetřující lékař věznice spolu s velitelem eskorty"]'::jsonb, 2, 'Propustku, základní doklad zdravotní eskorty, podepisuje vedoucí oddělení vězeňské stráže (VOVS) a v jeho nepřítomnosti službu konající vrchní inspektor strážní služby. Eskortní příkaz (k umístění či přemístění do jiné věznice) podepisuje ředitel věznice nebo jím pověřený zaměstnanec. (Právní úprava: NGŘ č. 33/2019, § 41 a § 73; učební text Eskortní služba, kapitola Propustka)', 'NGŘ č. 33/2019, § 41 a § 73; učební text Eskortní služba, kapitola Propustka', 'Eskortní služba – zdravotní eskorta'),
  ('Služební příprava', 'Jak předává velitel eskorty zdravotnickou dokumentaci eskortovaného ve zdravotnickém zařízení?', '["Ústně ji tlumočí lékaři podle svých poznámek", "Otevřenou ji předá kterékoli sestře na recepci ambulance", "Neveze ji, lékař si ji vyžádá od věznice", "V zapečetěné obálce s nápisem „Otevře lékař“ lékaři"]'::jsonb, 3, 'Zdravotnickou dokumentaci eskortovaného veze velitel eskorty v zapečetěné obálce s nápisem „Otevře lékař“ a předá ji lékaři nebo zdravotnickému pracovníkovi; není-li velen zdravotnický doprovod, plní tuto povinnost sám. (Právní úprava: § 43 NGŘ č. 33/2019; učební text Eskortní služba)', '§ 43 NGŘ č. 33/2019; učební text Eskortní služba', 'Eskortní služba – zdravotní eskorta'),
  ('Služební příprava', 'Kdo rozhoduje o sejmutí nebo nahrazení donucovacích prostředků eskortovaného v ordinaci po dobu nezbytně nutnou?', '["Velitel eskorty po konzultaci s lékařem", "Strážný, který vězně v ordinaci střeží", "Vrchní inspektor strážní služby telefonicky z věznice", "Ošetřující lékař, eskorta se musí podřídit"]'::jsonb, 0, 'O sejmutí nebo nahrazení donucovacích prostředků po dobu nezbytně nutnou rozhoduje po konzultaci s lékařem velitel eskorty. Stanovisko lékaře k omezení použití donucovacích prostředků uvedené v žádosti o eskortu je pro eskortu závazné. (Právní úprava: § 43 odst. 7 NGŘ č. 33/2019)', '§ 43 odst. 7 NGŘ č. 33/2019', 'Eskortní služba – zdravotní eskorta'),
  ('Právo', 'Jak je složen senát krajského soudu, který rozhoduje v prvním stupni?', '["Předseda senátu a čtyři přísedící", "Jeden soudce a dva přísedící", "Dva soudci a jeden přísedící", "Tři profesionální soudci"]'::jsonb, 1, 'Krajský soud v prvním stupni rozhoduje v senátu složeném z jednoho soudce a dvou přísedících; ve druhém stupni rozhoduje senát tří soudců. (Právní úprava: učební text Právo pro ZOP A (2022), kapitola Soudy – Obsazení soudů; § 17 zákona č. 141/1961 Sb.)', 'učební text Právo pro ZOP A (2022), kapitola Soudy – Obsazení soudů; § 17 zákona č. 141/1961 Sb.', 'Soustava soudů'),
  ('Služební příprava', 'Jak se podle NGŘ č. 16/2022 kvalifikuje náhlá změna zdravotního stavu vězněné osoby hrozící bezprostředním ohrožením života?', '["Jako běžná služební událost", "Jako krizová situace ve věznici", "Jako ostatní mimořádná událost", "Jako závažná mimořádná událost"]'::jsonb, 2, 'Náhlá změna zdravotního stavu vězněné osoby hrozící bezprostředním ohrožením života je ostatní mimořádnou událostí podle § 6 písm. c) NGŘ č. 16/2022; velitel eskorty ji neprodleně hlásí operačnímu středisku kmenové věznice. (Právní úprava: § 6 písm. c) NGŘ č. 16/2022)', '§ 6 písm. c) NGŘ č. 16/2022', 'Mimořádné události při eskortě'),
  ('Služební příprava', 'Jak se při přikládání pout s poutacím opaskem protahuje řetízek třmenem?', '["Zboku, aby řetízek nebránil v pohybu", "Na směru nezáleží, třmen řetízek vždy spolehlivě zajistí", "Odspodu, aby se pouta nemohla přetočit", "Odshora, protože odspodu z třmenu vypadává"]'::jsonb, 3, 'Po kontrole opasku se řetízek protahuje třmenem odshora, protože odspodu má tendenci z třmenu vypadnout; je-li třeba jej zkrátit, obtočí se kolem opasku a třmenem se opět protáhne odshora. (Právní úprava: Metodika poutání, kapitola Taktický postup při přikládání pout s poutacím opaskem, s. 18–23)', 'Metodika poutání, kapitola Taktický postup při přikládání pout s poutacím opaskem, s. 18–23', 'Poutání – pouta s poutacím opaskem'),
  ('Služební příprava', 'Jak často a v jakém rozsahu se nejméně provádí generální prohlídka?', '["Nejméně jedenkrát ročně v rozsahu celé věznice", "Nejméně jedenkrát za 90 dnů na všech celách", "Nejméně dvakrát ročně jen v ubytovacích prostorech", "Nejméně jednou měsíčně v rozsahu celé věznice"]'::jsonb, 0, 'Generální prohlídka se provádí minimálně jedenkrát ročně v rozsahu celé věznice a její součástí je vždy osobní prohlídka všech vězněných osob v prohlížené části. Interval 90 dnů platí pro dílčí prohlídku. (Právní úprava: § 89 až § 92 NGŘ č. 33/2019; učební text Prohlídky, s. 2–3)', '§ 89 až § 92 NGŘ č. 33/2019; učební text Prohlídky, s. 2–3', 'Prohlídky – generální prohlídka'),
  ('Služební příprava', 'Kdo může rozhodnout o provedení dílčí nebo technické prohlídky mimo stanovený plán?', '["Pouze generální ředitel Vězeňské služby ČR", "Vedoucí oddělení nebo vrchní inspektor strážní služby", "Kterýkoliv dozorce na svém stanovišti", "Výhradně ředitel věznice svým písemným nařízením pro každý případ"]'::jsonb, 1, 'V zájmu prevence a v odůvodněných případech se dílčí nebo technická prohlídka provádí i mimo plán; rozhodnout o ní může vedoucí oddělení nebo VISS a jejich nadřízení ve spolupráci s funkcionáři oddělení výkonu trestu. (Právní úprava: § 90 NGŘ č. 33/2019; učební text Prohlídky)', '§ 90 NGŘ č. 33/2019; učební text Prohlídky', 'Prohlídky – dílčí a technická prohlídka'),
  ('Vězeňská administrativa', 'Kam zapíše příslušník odpovědný za řízení dílčí prohlídky stručný záznam o jejím provedení?', '["Do staniční knihy dozorce na oddílu", "Do osobních spisů všech vězňů z prohlížených cel", "Do Knihy dílčích (technických) prohlídek", "Do Knihy hlášení vrchního inspektora"]'::jsonb, 2, 'Po prohlídce se zpracuje stručný záznam do Knihy dílčích (technických) prohlídek s datem, časem od–do, místem, kdo prohlídku provedl, co a u koho bylo nalezeno a jaké nedostatky byly zjištěny. (Právní úprava: § 92 odst. 4 NGŘ č. 33/2019)', '§ 92 odst. 4 NGŘ č. 33/2019', 'Dokumentace prohlídek'),
  ('Služební příprava', 'Jak se podle NGŘ č. 16/2022 kvalifikuje zjištění prokazatelné přípravy k útěku vězněné osoby, například naříznuté okenní mříže?', '["Jako událost bez povinnosti hlášení", "Pouze jako kázeňský přestupek", "Jako ostatní mimořádná událost", "Jako závažná mimořádná událost"]'::jsonb, 3, 'Útěk, pokus o útěk nebo prokazatelná příprava k útěku je závažnou mimořádnou událostí podle § 5 písm. a) NGŘ č. 16/2022; zjištění se neprodleně hlásí přímému nadřízenému. (Právní úprava: § 3 písm. c) a § 5 písm. a) NGŘ č. 16/2022)', '§ 3 písm. c) a § 5 písm. a) NGŘ č. 16/2022', 'Mimořádné události – příprava k útěku'),
  ('Právo', 'Podle kterého ustanovení trestního zákoníku se posuzuje útěk z vazby nebo z výkonu trestu odnětí svobody?', '["§ 337 odst. 3 písm. b) TZ", "§ 325 odst. 1 písm. a) TZ", "§ 344 odst. 1 a 2 TZ", "§ 329 odst. 1 písm. a) a b) TZ"]'::jsonb, 0, 'Útěk z vazby nebo z výkonu trestu odnětí svobody je trestným činem podle § 337 odst. 3 písm. b) TZ se sazbou odnětí svobody až na pět let; naříznutí mříže lze podle okolností posoudit jako jeho pokus (§ 21 TZ). (Právní úprava: § 337 odst. 3 písm. b) zákona č. 40/2009 Sb.)', '§ 337 odst. 3 písm. b) zákona č. 40/2009 Sb.', 'Trestné činy – útěk vězněné osoby'),
  ('Služební příprava', 'Jak postupuje příslušník, zjistí-li při osobní prohlídce předmět zašitý do oděvní součásti?', '["Vyzve vězně, ať předmět před ostatními sám vyndá", "Nařídí oděv svléknout, odpáře jej a předmět odebere", "Látku na místě rozstřihne a předmět vyjme", "Oděvní součást i s předmětem zabaví a nechá ji zlikvidovat"]'::jsonb, 1, 'Je-li předmět zašit do oděvní součásti, příslušník nařídí ji svléknout, odpáře ji a předmět odebere; látku netrhá ani nestříhá. Neptá se před ostatními vězni, od koho věc má. Věc odejme podle § 12 zákona č. 555/1992 Sb. (Právní úprava: § 12 zákona č. 555/1992 Sb.; učební text Prohlídky, s. 7–8)', '§ 12 zákona č. 555/1992 Sb.; učební text Prohlídky, s. 7–8', 'Preventivní osobní prohlídka'),
  ('Služební příprava', 'Kdo v pracovní době rozhoduje o provedení osobní prohlídky vstupující osoby?', '["Ředitel věznice nebo jeho první zástupce", "Strážný u hlavního vchodu sám", "Vedoucí oddělení vězeňské stráže", "Inspektor strážní služby na stanovišti"]'::jsonb, 2, 'O osobní prohlídce vstupující osoby rozhoduje v pracovní době vedoucí oddělení vězeňské stráže (VOVS), v mimopracovní době VISS. Provádí ji osoba stejného pohlaví v určené místnosti. (Právní úprava: § 99 NGŘ č. 33/2019)', '§ 99 NGŘ č. 33/2019', 'Kontrola vstupujících osob'),
  ('Služební příprava', 'Je dohledání kovového předmětu ručním detektorem u vstupující osoby osobní prohlídkou?', '["Ano, vyžaduje proto souhlas VOVS nebo VISS", "Ne, lze ji však provést jen se souhlasem ředitele", "Ano, provádí ji osoba stejného pohlaví", "Ne, není jí a nevyžaduje odkládání oděvu"]'::jsonb, 3, 'Při přetrvávající signalizaci detekčního rámu je strážný povinen provést dohledání ručním detektorem kovů; nejde o osobní prohlídku a nevyžaduje odkládání oděvu. (Právní úprava: § 101 odst. 3 NGŘ č. 33/2019)', '§ 101 odst. 3 NGŘ č. 33/2019', 'Kontrola vstupujících osob'),
  ('Služební příprava', 'Jaký je důsledek, odmítne-li návštěvnice podrobit se osobní prohlídce při vstupu do věznice?', '["Neumožní se jí vstup do střeženého objektu", "Prohlídka se provede i bez jejího souhlasu", "K provedení prohlídky se přivolá Policie ČR", "Vstoupí jen v doprovodu příslušníka"]'::jsonb, 0, 'Osoba má právo osobní prohlídku odmítnout; musí být poučena, že důsledkem je neumožnění vstupu do střeženého objektu. Zvukový signál rámu nebo detektoru je přitom důvodným podezřením podle § 99 odst. 2. (Právní úprava: § 99 odst. 2 a 3 NGŘ č. 33/2019)', '§ 99 odst. 2 a 3 NGŘ č. 33/2019', 'Kontrola vstupujících osob'),
  ('Služební příprava', 'Na jak dlouho nejvýše lze vydat zvláštní povolení ke vstupu do střeženého objektu?', '["Nejdéle na jeden měsíc", "Nejdéle na jeden rok", "Nejdéle na šest měsíců", "Nejdéle na tři roky"]'::jsonb, 1, 'Zvláštní povolení vydává ředitel věznice nebo generální ředitel zaměstnancům jiných subjektů plnícím úkoly ze smluv s Vězeňskou službou; platí jen s průkazem totožnosti, nejdéle na jeden rok, a je uloženo na hlavním vstupu. (Právní úprava: § 103 písm. d) NGŘ č. 33/2019)', '§ 103 písm. d) NGŘ č. 33/2019', 'Vstup do střežených objektů'),
  ('Penologie', 'Umožní se vstup do prostor pro návštěvy návštěvníkovi obviněného, který předloží jen potvrzení o ztrátě občanského průkazu?', '["Ano, potvrzení má stejnou platnost", "Ano, se souhlasem vrchního inspektora strážní služby", "Ne, vyžaduje se platný občanský průkaz nebo pas", "Ano, pokud jej doprovází jiná zletilá osoba"]'::jsonb, 2, 'Návštěvníkům obviněných se umožní vstup do prostor pro návštěvy po předložení platného občanského průkazu nebo pasu; vstup na potvrzení o ztrátě občanského průkazu se neumožní. (Právní úprava: § 44 odst. 2 vyhlášky č. 109/1994 Sb.)', '§ 44 odst. 2 vyhlášky č. 109/1994 Sb.', 'Návštěvy obviněných'),
  ('Služební příprava', 'Kdo zavádí strážné na strážní stanoviště při jejich střídání?', '["Vrchní inspektor strážní služby střídající směny", "Operační středisko věznice prostřednictvím radiostanice", "Střídaný strážný po předání stanoviště", "Inspektor strážní služby střídané a střídající směny"]'::jsonb, 3, 'Střídání se provádí po rozdílení směny a nabití zbraní; strážné na stanoviště zavádí inspektor strážní služby (ISS) střídané a střídající směny. VISS obou směn pak převezmou hlášení a podepíší předání v Knize hlášení VISS. (Právní úprava: § 51 NGŘ č. 33/2019; učební text Strážní služba (Kupec), s. 20–21)', '§ 51 NGŘ č. 33/2019; učební text Strážní služba (Kupec), s. 20–21', 'Střídání strážných'),
  ('Služební příprava', 'Komu je zaměstnanec povinen nahlásit mimořádnou událost, o níž se dozví v době mimo službu?', '["Službu konajícímu VISS, resp. operačnímu středisku", "Pouze Policii České republiky na lince 158", "Svému přímému nadřízenému při nástupu do služby", "Písemně řediteli věznice do tří pracovních dnů od zjištění"]'::jsonb, 0, 'Mimořádnou událost je zaměstnanec povinen nahlásit neprodleně – v době služby svému přímému nadřízenému, v době mimo službu službu konajícímu vrchnímu inspektorovi strážní služby, respektive operačnímu středisku. (Právní úprava: § 3 písm. c) NGŘ č. 16/2022)', '§ 3 písm. c) NGŘ č. 16/2022', 'Mimořádné události – hlášení'),
  ('Služební příprava', 'Jak se naloží s hlášením o pokusu o sebevraždu vězněné osoby, jestliže lékař následně konstatuje smrt?', '["Zpracuje se nové hlášení a původní se skartuje jako neplatné", "Překvalifikuje se dodatkem na sebevraždu", "Původní hlášení se zruší bez náhrady", "Hlášení se nemění, smrt šetří jen policie"]'::jsonb, 1, 'Pokus o sebevraždu s přímým ohrožením života je ostatní mimořádnou událostí podle § 6 písm. a); konstatuje-li lékař smrt, událost se dodatkem překvalifikuje na sebevraždu podle § 15 odst. 3 NGŘ č. 16/2022. (Právní úprava: § 6 písm. a) a § 15 odst. 3 NGŘ č. 16/2022)', '§ 6 písm. a) a § 15 odst. 3 NGŘ č. 16/2022', 'Mimořádné události – hlášení'),
  ('Právo', 'Proti komu je přípustná nutná obrana, útočí-li současně více osob?', '["Jen proti tomu, kdo útok vede", "Jen proti útočníkovi, který je nejblíž", "Proti kterémukoliv z útočících osob", "Proti nikomu, jde pak jen o krajní nouzi"]'::jsonb, 2, 'Obrana musí směřovat proti útočníkovi, čímž se liší od krajní nouze; útočí-li více osob, je nutná obrana přípustná proti kterémukoliv z nich. (Právní úprava: § 29 zákona č. 40/2009 Sb.; učební text Právo pro ZOP A (2022), kapitola Okolnosti vylučující protiprávnost)', '§ 29 zákona č. 40/2009 Sb.; učební text Právo pro ZOP A (2022), kapitola Okolnosti vylučující protiprávnost', 'Nutná obrana'),
  ('Právo', 'Lze se bránit v nutné obraně proti jednání osoby, která sama jedná v nutné obraně?', '["Ano, nutná obrana je přípustná vždy", "Ne, pokud útočník nebyl předem varován výzvou", "Ano, pokud je obrana přiměřená", "Ne, proti jednání dovolenému ji použít nelze"]'::jsonb, 3, 'Nutnou obranu nelze použít proti jednání dovolenému, například proti jednání v nutné obraně nebo krajní nouzi nebo proti výkonu práva či povinnosti policisty. (Právní úprava: § 29 zákona č. 40/2009 Sb.; učební text Právo pro ZOP A (2022), kapitola Okolnosti vylučující protiprávnost)', '§ 29 zákona č. 40/2009 Sb.; učební text Právo pro ZOP A (2022), kapitola Okolnosti vylučující protiprávnost', 'Nutná obrana'),
  ('Psychologie', 'Které z uvedených faktorů podle učebního textu psychologie nasvědčují vysoké pravděpodobnosti sebevražedného jednání?', '["Mužské pohlaví a věk nad 40 let", "Stabilní rodina a pravidelné návštěvy", "Ženské pohlaví a věk pod 25 let", "Krátký trest a první uvěznění"]'::jsonb, 0, 'Mezi faktory vysoké pravděpodobnosti sebeohrožení patří sebevražedné pokusy v anamnéze a v příbuzenstvu, beznaděj, chronická nemoc, abúzus alkoholu nebo drog, osamělost, věk nad 40 let a mužské pohlaví. (Právní úprava: učební text Psychologie pro ZOP (Akademie VS ČR, 2023), kapitola Sebevražedné (suicidiální) jednání, s. 73–75)', 'učební text Psychologie pro ZOP (Akademie VS ČR, 2023), kapitola Sebevražedné (suicidiální) jednání, s. 73–75', 'Suicidální chování vězňů'),
  ('Penologie', 'Koho věznice vždy bez odkladu vyrozumí o úmrtí obviněného?', '["Pouze dozorového státního zástupce a ombudsmana", "Příslušný OČTŘ a osobu určenou obviněným či osobu blízkou", "Pouze osobu blízkou, a to do 30 dnů od úmrtí", "Pouze Policii ČR a ošetřujícího lékaře zdravotnického střediska"]'::jsonb, 1, 'Podle § 18 odst. 7 zákona o výkonu vazby věznice o úmrtí obviněného vždy bez odkladu vyrozumí příslušný orgán činný v trestním řízení a osobu, kterou obviněný určil, nebo osobu blízkou. (Právní úprava: § 18 odst. 7 zákona č. 293/1993 Sb.)', '§ 18 odst. 7 zákona č. 293/1993 Sb.', 'Úmrtí obviněného'),
  ('Penologie', 'Po jaké době od výkonu předchozího trestu lze nejdříve začít vykonávat znovu uložené celodenní umístění do uzavřeného oddílu nebo samovazbu (nebyl-li trest uložen ještě v průběhu výkonu)?', '["Nejdříve po uplynutí 5 dnů od výkonu předchozího trestu", "Nejdříve po uplynutí 14 dnů od skončení předchozího trestu", "Nejdříve po uplynutí 10 dnů od výkonu předchozího trestu", "Ihned, výkon může navazovat bez jakékoli přestávky"]'::jsonb, 2, 'S výkonem znovu uloženého celodenního umístění do uzavřeného oddílu nebo samovazby nelze začít dříve než po uplynutí 10 dnů od výkonu předchozího trestu, ledaže byl uložen ještě v průběhu jeho výkonu. (Právní úprava: § 49 zákona č. 169/1999 Sb.)', '§ 49 zákona č. 169/1999 Sb.', 'Kázeňské tresty – uzavřený oddíl'),
  ('Penologie', 'Jakou nejdelší zkušební dobu lze stanovit při podmíněném uložení umístění do uzavřeného oddílu nebo celodenního umístění do uzavřeného oddílu?', '["Zkušební dobu až na 6 měsíců", "Zkušební dobu až na 12 měsíců", "Zkušební dobu až na 3 měsíce", "Zkušební dobu až na 1 měsíc"]'::jsonb, 0, 'Výkon kázeňských trestů podle § 46 odst. 3 písm. f) a g) lze podle § 46 odst. 4 zákona č. 169/1999 Sb. uložit i podmíněně se zkušební dobou až na 6 měsíců. (Právní úprava: § 46 odst. 4 zákona č. 169/1999 Sb.)', '§ 46 odst. 4 zákona č. 169/1999 Sb.', 'Kázeňské tresty – podmíněné uložení'),
  ('Penologie', 'Na jak dlouho lze nejvýše uložit dospělému obviněnému ve výkonu vazby kázeňský trest umístění do samovazby?', '["Až na pět dnů", "Až na sedm dnů", "Až na dvacet dnů", "Až na deset dnů"]'::jsonb, 3, 'U obviněných se podle § 22 zákona č. 293/1993 Sb. vykonává umístění do samovazby až na 10 dnů (u mladistvých obviněných nejdéle 5 dní); 20 dnů je horní hranice u odsouzených. (Právní úprava: § 22 odst. 2 písm. e) zákona č. 293/1993 Sb.)', '§ 22 odst. 2 písm. e) zákona č. 293/1993 Sb.', 'Kázeňské tresty – obvinění'),
  ('Penologie', 'U kterého kázeňského trestu uloženého odsouzenému má stížnost odkladný účinek?', '["Jen u samovazby a celodenního umístění do UO", "Jen u kázeňského trestu propadnutí věci", "U všech ukládaných kázeňských trestů", "Jen u pokuty a snížení kapesného"]'::jsonb, 1, 'Podle § 52 odst. 1 zákona č. 169/1999 Sb. má stížnost odkladný účinek jen u propadnutí věci; ostatní tresty (např. umístění do uzavřeného oddílu) jsou vykonatelné oznámením rozhodnutí. (Právní úprava: § 52 odst. 1 zákona č. 169/1999 Sb.; § 31 odst. 2 NGŘ č. 41/2024)', '§ 52 odst. 1 zákona č. 169/1999 Sb.; § 31 odst. 2 NGŘ č. 41/2024', 'Kázeňské řízení – stížnost'),
  ('Služební příprava', 'Jak je podle NGŘ č. 16/2022 klasifikováno sebepoškození vězněné osoby s následkem přímého ohrožení jejího života?', '["Závažná mimořádná událost podle § 5 písm. a)", "Kázeňský přestupek bez hlášení události", "Ostatní mimořádná událost podle § 6 písm. a)", "Závažná mimořádná událost podle § 5 písm. b) NGŘ"]'::jsonb, 2, 'Sebepoškození vězněné osoby s následkem přímého ohrožení života je ostatní mimořádnou událostí podle § 6 písm. a) NGŘ č. 16/2022; zároveň porušuje zákaz úmyslně se poškozovat na zdraví podle § 28 odst. 3 písm. f) zákona č. 169/1999 Sb. (Právní úprava: § 6 písm. a) NGŘ č. 16/2022)', '§ 6 písm. a) NGŘ č. 16/2022', 'Mimořádné události – sebepoškození'),
  ('Psychologie', 'Který projev sebepoškození podle učebního textu psychologie svědčí pro motivaci odstraněním vnitřní psychické tenze?', '["Mnoho mělkých chaotických řezů na předloktích", "Spolykání většího množství léků", "Sypání tuhy z propisovací tužky do očí", "Plánovité polykání cizích předmětů před soudem"]'::jsonb, 0, 'Pro motivaci odstraněním vnitřní psychické tenze svědčí automutilace pořezáním mnoha mělkými chaotickými řezy, jakoby posekáním, nejčastěji na předloktích; takové chování lze často předvídat. (Právní úprava: učební text Psychologie pro ZOP (2023), kapitola Sebevražedné jednání a sebepoškozování)', 'učební text Psychologie pro ZOP (2023), kapitola Sebevražedné jednání a sebepoškozování', 'Automutilace – motivace'),
  ('Služební příprava', 'Které místo ve vozidle nesmí podle zásad pro eskorty motorovými vozidly eskortovaná osoba zaujmout?', '["Místo v uzamykatelné kóji vozidla", "Místo vedle strážného eskorty", "Jakékoli místo v zadní části vozu", "Místo bezprostředně za řidičem"]'::jsonb, 3, 'Rozmístění eskortovaných ve vozidle stanoví velitel eskorty; eskortovaní nesmějí sedět bezprostředně za řidičem (§ 41 odst. 1 NGŘ č. 33/2019). (Právní úprava: § 41 odst. 1 NGŘ č. 33/2019)', '§ 41 odst. 1 NGŘ č. 33/2019', 'Eskorta motorovým vozidlem'),
  ('Služební příprava', 'Kdo rozhoduje o odemčení speciálních technických prostředků, jimiž jsou vězněné osoby zajištěny ve vozidle během eskorty?', '["Operační středisko kmenové věznice", "Výhradně velitel eskorty", "Strážný – řidič vozidla", "Vrchní inspektor strážní služby"]'::jsonb, 1, 'Za uzamčení speciálních technických prostředků ve vozidle odpovídá velitel eskorty, který jako jediný rozhoduje o jejich odemčení (§ 41 odst. 1 NGŘ č. 33/2019). (Právní úprava: § 41 odst. 1 NGŘ č. 33/2019)', '§ 41 odst. 1 NGŘ č. 33/2019', 'Eskorta motorovým vozidlem'),
  ('Služební příprava', 'Za jaké podmínky smí velitel eskorty přepravovat eskortním vozidlem osoby, které nejsou členy eskorty?', '["Jen se souhlasem operačního střediska věznice", "Kdykoli, je-li ve vozidle volné místo", "Jen se souhlasem vedoucího oddělení nebo ředitele věznice", "Jen na písemnou žádost předsedy senátu nebo soudce, který jedná"]'::jsonb, 2, 'Podle § 73 odst. 4 NGŘ č. 33/2019 velitel eskorty nesmí eskortním vozidlem bez souhlasu vedoucího oddělení nebo ředitele věznice přepravovat osoby, které nejsou členy eskorty. (Právní úprava: § 73 odst. 4 NGŘ č. 33/2019)', '§ 73 odst. 4 NGŘ č. 33/2019', 'Zákazy velitele eskorty'),
  ('Služební příprava', 'Kdo určuje polohu, v níž je přepravována osoba eskortovaná do zdravotnického zařízení nebo z něj?', '["Ošetřující lékař podle zdravotního stavu", "Velitel eskorty podle počtu míst", "Strážný – řidič podle typu vozidla", "Vedoucí oddělení vězeňské stráže podle rizik"]'::jsonb, 0, 'Osoby eskortované do zdravotnického zařízení nebo z něj jsou přepravovány v poloze, kterou určí ošetřující lékař podle jejich zdravotního stavu; zohledňují se i jím stanovená režimová opatření. (Právní úprava: § 41 odst. 1 NGŘ č. 33/2019)', '§ 41 odst. 1 NGŘ č. 33/2019', 'Eskorta do zdravotnického zařízení'),
  ('Služební příprava', 'Jak se podle NGŘ č. 33/2019 dělí eskorty podle způsobu provádění?', '["Na eskorty řádné, mimořádné a jiné", "Na eskorty soudní, zdravotní a přemísťovací", "Na eskorty vnitřní, vnější, mezistátní a letecké", "Na eskorty motorovými vozidly, pěší a letecké"]'::jsonb, 3, 'Podle způsobu provádění se rozeznávají eskorty motorovými vozidly, pěší eskorty a letecké eskorty; soudní, zdravotní a přemísťovací jsou dělení podle účelu. (Právní úprava: § 39 odst. 2 NGŘ č. 33/2019)', '§ 39 odst. 2 NGŘ č. 33/2019', 'Druhy eskort'),
  ('Služební příprava', 'Jak je podle NGŘ č. 16/2022 klasifikováno úmrtí vězněné osoby?', '["Závažná mimořádná událost podle § 5 písm. b)", "Ostatní mimořádná událost podle § 6 písm. b)", "Událost hlášená pouze řediteli věznice", "Závažná mimořádná událost podle § 5 písm. a) NGŘ"]'::jsonb, 1, 'Úmrtí vězněné osoby je podle § 6 písm. b) NGŘ č. 16/2022 ostatní mimořádnou událostí (nikoliv závažnou); organizační jednotka ji podle § 7 hlásí stálé službě generálního ředitelství a dozorovému státnímu zástupci. (Právní úprava: § 6 písm. b) a § 7 NGŘ č. 16/2022)', '§ 6 písm. b) a § 7 NGŘ č. 16/2022', 'Mimořádné události – úmrtí'),
  ('Služební příprava', 'Za jakých podmínek smí velitel eskorty o přestávce soudního jednání umožnit rozmluvu obviněného s obhájcem nebo rodinným příslušníkem?', '["Kdykoli, ale jen v odkládací cele za dozoru", "Jen se souhlasem operačního střediska věznice", "Jen se svolením předsedy senátu a mimo eskortní cely", "Nikdy, rozmluva je během eskorty vždy a bez výjimky zakázána"]'::jsonb, 2, 'Rozmluvu vězněné osoby s obhájcem nebo rodinným příslušníkem velitel eskorty umožní pouze se svolením předsedy senátu, v místě jím určeném, vždy mimo eskortní cely; nedovolí předávání balíčků ani jiných předmětů. (Právní úprava: § 73 NGŘ č. 33/2019; učební text Eskortní služba)', '§ 73 NGŘ č. 33/2019; učební text Eskortní služba', 'Eskorta k soudu'),
  ('Právo', 'V jaké lhůtě musí státní zástupce předložit soudci žádost obviněného o propuštění z vazby, jestliže jí sám nevyhoví?', '["Do pěti pracovních dnů", "Do tří pracovních dnů", "Do deseti kalendářních dnů", "Do 24 hodin od podání"]'::jsonb, 0, 'Podle § 73b trestního řádu rozhoduje o žádosti v přípravném řízení státní zástupce; nevyhoví-li jí, musí ji do pěti pracovních dnů předložit soudci. (Právní úprava: § 73b zákona č. 141/1961 Sb.)', '§ 73b zákona č. 141/1961 Sb.', 'Vazba – žádost o propuštění'),
  ('Právo', 'Jaká je nejvyšší přípustná doba trvání vazby, je-li obviněný stíhán pro přečin?', '["Šest měsíců", "Tři měsíce", "Dva roky", "Jeden rok"]'::jsonb, 3, 'Podle § 72a trestního řádu činí nejvyšší přípustná doba vazby jeden rok u přečinu, dva roky u zločinu, tři roky u zvlášť závažného zločinu a čtyři roky u zvlášť závažného zločinu s možností výjimečného trestu. (Právní úprava: § 72a zákona č. 141/1961 Sb.)', '§ 72a zákona č. 141/1961 Sb.', 'Vazba – nejvyšší přípustná doba'),
  ('Služební příprava', 'Do kolika dnů se má propuštěný eskortovaný podle poučení velitele eskorty dostavit do věznice k vyřízení náležitostí spojených s propuštěním?', '["Ihned v den propuštění", "Do tří dnů od propuštění", "Do osmi dnů od propuštění", "Do patnácti dnů od propuštění"]'::jsonb, 1, 'Velitel eskorty podle § 73 odst. 1 písm. w) NGŘ č. 33/2019 prokazatelně poučí eskortovaného, že se má do 3 dnů dostavit do věznice (převzetí osobních věcí, dokladů a peněz); propuštěný to stvrdí podpisem na příkazu k propuštění. (Právní úprava: § 73 odst. 1 písm. w) NGŘ č. 33/2019)', '§ 73 odst. 1 písm. w) NGŘ č. 33/2019', 'Propuštění obviněného přímo od soudu'),
  ('Služební příprava', 'Jak je podle NGŘ č. 16/2022 klasifikováno napadení eskorty?', '["Ostatní mimořádná událost podle § 6 písm. b)", "Narušení průběhu eskorty bez hlášení", "Závažná mimořádná událost podle § 5 písm. b)", "Ostatní mimořádná událost podle § 6 písm. a) NGŘ"]'::jsonb, 2, 'Napadení eskorty je podle § 5 písm. b) NGŘ č. 16/2022 závažnou mimořádnou událostí, kterou věznice neprodleně hlásí stálé službě generálního ředitelství a dozorovému státnímu zástupci. (Právní úprava: § 5 písm. b) a § 7 NGŘ č. 16/2022)', '§ 5 písm. b) a § 7 NGŘ č. 16/2022', 'Mimořádné události – napadení eskorty'),
  ('Služební příprava', 'V jakém minimálním rozsahu se provádí preventivní osobní prohlídka před odjezdem vězněných osob na pracoviště mimo věznici?', '["U všech vězněných osob pracovní čety", "Jen při důvodném podezření u konkrétní osoby", "Nejméně u 5 % čety, nejméně však u 2 osob", "Nejméně u 10 % čety, nejméně však u 4 osob"]'::jsonb, 3, 'Podle § 96 odst. 1 písm. g) NGŘ č. 33/2019 se preventivní osobní prohlídka před odjezdem na pracoviště provádí nejméně u 10 procent pracovní čety, nejméně však u 4 vězněných osob; před odchodem z pracoviště a při návratu u všech. (Právní úprava: § 96 odst. 1 písm. g) NGŘ č. 33/2019)', '§ 96 odst. 1 písm. g) NGŘ č. 33/2019', 'Osobní prohlídky – nestřežené pracoviště'),
  ('Penologie', 'Jak často musí dozorce nejméně kontrolovat odsouzené z oddělení se středním stupněm zabezpečení na nestřeženém pracovišti?', '["Nejméně jedenkrát za směnu", "Nejméně jedenkrát za hodinu", "Nejméně jedenkrát týdně", "Nejméně jedenkrát za čtvrt hodiny"]'::jsonb, 1, 'Podle § 52 odst. 3 vyhlášky č. 345/1999 Sb. se odsouzení z oddělení se středním stupněm zabezpečení na nestřeženém pracovišti kontrolují nejméně jedenkrát za hodinu; u nízkého stupně zabezpečení nejméně jedenkrát týdně. (Právní úprava: § 52 odst. 3 vyhlášky č. 345/1999 Sb.)', '§ 52 odst. 3 vyhlášky č. 345/1999 Sb.', 'Nestřežené pracoviště – kontroly'),
  ('Penologie', 'Na jak dlouho může vychovatel nejvýše uložit odsouzenému umístění do uzavřeného oddílu?', '["Až na tři dny", "Až na čtrnáct dnů", "Až na sedm dnů", "Až na pět dnů"]'::jsonb, 2, 'Podle přílohy č. 1c NGŘ č. 41/2024 může vychovatel uložit umístění do uzavřeného oddílu až na 7 dnů; nemůže uložit zákaz přijetí balíčku, pokutu, celodenní umístění ani samovazbu. (Právní úprava: příloha č. 1c NGŘ č. 41/2024)', 'příloha č. 1c NGŘ č. 41/2024', 'Kázeňská pravomoc – rozsah'),
  ('Penologie', 'Do jaké výše může speciální pedagog uložit odsouzenému kázeňský trest pokuty?', '["Až do výše 2 000 Kč", "Až do výše 500 Kč", "Až do výše 3 000 Kč", "Pokutu vůbec uložit nemůže"]'::jsonb, 0, 'Speciální pedagog může podle přílohy č. 1c NGŘ č. 41/2024 uložit pokutu až 2 000 Kč; zástupce vedoucího i vedoucí oddělení až 3 000 Kč, první zástupce ředitele a ředitel věznice až 5 000 Kč. (Právní úprava: příloha č. 1c NGŘ č. 41/2024)', 'příloha č. 1c NGŘ č. 41/2024', 'Kázeňská pravomoc – rozsah'),
  ('Penologie', 'Jaké oprávnění má dozorce v kázeňském řízení vůči odsouzenému, který se opil na pracovišti?', '["Může sám uložit důtku nebo propadnutí věci", "Nemá žádné, vše řeší vychovatel", "Může uložit umístění do uzavřeného oddílu na 7 dnů", "Může zpracovat záznam o kázeňském přestupku"]'::jsonb, 3, 'Dozorce kázeňskou pravomoc nemá; podle § 16 NGŘ č. 41/2024 může kterýkoliv zaměstnanec zpracovat záznam o kázeňském přestupku, který předá zaměstnanci s kázeňskou pravomocí. (Právní úprava: § 16 NGŘ č. 41/2024)', '§ 16 NGŘ č. 41/2024', 'Kázeňské řízení – role dozorce'),
  ('Služební příprava', 'Jak je podle NGŘ č. 16/2022 klasifikován pozitivní výsledek opakované dechové zkoušky na alkohol u vězněné osoby?', '["Závažná mimořádná událost podle § 5 písm. f)", "Ostatní mimořádná událost podle § 6 písm. f)", "Kázeňský přestupek bez hlášení události", "Závažná mimořádná událost podle § 5 písm. h) NGŘ"]'::jsonb, 1, 'Pozitivní výsledek opakované dechové zkoušky je podle § 6 písm. f) NGŘ č. 16/2022 ostatní mimořádnou událostí; odsouzený je povinen podrobit se vyšetření podle § 28 odst. 2 písm. n) zákona č. 169/1999 Sb. (Právní úprava: § 6 písm. f) NGŘ č. 16/2022)', '§ 6 písm. f) NGŘ č. 16/2022', 'Mimořádné události – alkohol'),
  ('Služební příprava', 'Jak je podle NGŘ č. 16/2022 klasifikován pokus o útěk odsouzeného při eskortě do mimovězeňského zdravotnického zařízení?', '["Ostatní mimořádná událost podle § 6 písm. e)", "Narušení eskorty hlášené jen VISS", "Závažná mimořádná událost podle § 5 písm. a)", "Ostatní mimořádná událost podle § 6 písm. a) NGŘ"]'::jsonb, 2, 'Pokus o útěk při eskortě je závažnou mimořádnou událostí podle § 5 písm. a) NGŘ č. 16/2022; věznice ji podle § 7 hlásí stálé službě generálního ředitelství a dozorovému státnímu zástupci. (Právní úprava: § 5 písm. a) a § 7 NGŘ č. 16/2022)', '§ 5 písm. a) a § 7 NGŘ č. 16/2022', 'Mimořádné události – pokus o útěk'),
  ('Právo', 'Kterých trestných činů hlavy XII trestního zákoníku se příslušník Vězeňské služby jako pachatel dopustit nemůže?', '["Neuposlechnutí rozkazu (§ 375 a § 376)", "Porušení povinnosti strážní (§ 389) a dozorčí služby (§ 390)", "Urážka (§ 378) a násilí vůči nadřízenému (§ 381)", "Zběhnutí (§ 386) a svémocné odloučení (§ 387)"]'::jsonb, 3, 'Příslušník bezpečnostního sboru je vojákem jen u činů vyjmenovaných v § 114 odst. 4 trestního zákoníku (mj. § 375, § 376, § 378, § 381, § 389, § 390); zběhnutí (§ 386) ani svémocné odloučení (§ 387) mezi nimi nejsou. (Právní úprava: § 114 odst. 4, § 386 a § 387 zákona č. 40/2009 Sb.)', '§ 114 odst. 4, § 386 a § 387 zákona č. 40/2009 Sb.', 'Trestné činy vojenské – příslušník VS'),
  ('Právo', 'Jakým trestem odnětí svobody je ohroženo porušení povinnosti dozorčí nebo jiné služby podle § 390 trestního zákoníku?', '["Až na šest měsíců", "Až na jeden rok", "Až na tři léta", "Na šest měsíců až pět let"]'::jsonb, 1, 'Kdo v dozorčí nebo jiné službě, byť i z nedbalosti, poruší předpisy nebo pravidla této služby, bude podle § 390 potrestán odnětím svobody až na jeden rok; u porušení povinnosti strážní služby (§ 389) je to až tři léta. (Právní úprava: § 390 zákona č. 40/2009 Sb.)', '§ 390 zákona č. 40/2009 Sb.', 'Trestné činy vojenské – sazby'),
  ('Služební příprava', 'Kdy provádí velitel eskorty poučení eskortovaného o jeho právech a povinnostech?', '["Až po příjezdu na místo určení eskorty", "Po přiložení DP, těsně před nástupem do eskortního vozidla", "Před odjezdem, před prohlídkou a přiložením DP", "Jen na výslovnou žádost eskortovaného"]'::jsonb, 2, 'Poučení je povinností velitele eskorty podle § 73 odst. 1 písm. d) NGŘ č. 33/2019; provádí se před odjezdem, po převzetí vězněné osoby podle propustky a identifikační karty a před osobní prohlídkou a přiložením donucovacích prostředků. (Právní úprava: § 73 odst. 1 písm. d) NGŘ č. 33/2019)', '§ 73 odst. 1 písm. d) NGŘ č. 33/2019', 'Poučení před eskortou'),
  ('Služební příprava', 'Může dozorce vyzbrojený střelnou zbraní použít zbraň proti odsouzenému, který svévolně a bez útoku odchází z nestřeženého pracoviště mimo věznici?', '["Ne, nejde o střežený objekt ani o eskortu a odsouzený neútočí", "Ano, jde o útěk ze střeženého objektu podle § 18 odst. 1 písm. c)", "Ano, ale jen po předchozím varovném výstřelu", "Ano, pokud to předem schválí operační středisko věznice"]'::jsonb, 0, 'Důvod podle § 18 odst. 1 písm. c) zákona č. 555/1992 Sb. se nevztahuje: nestřežené pracoviště není střeženým objektem (§ 30 odst. 5 NGŘ č. 33/2019) a převoz na nestřežené pracoviště není eskortou (§ 37 odst. 3). Lze použít jen donucovací prostředky podle § 17. (Právní úprava: § 18 zákona č. 555/1992 Sb.; § 30 odst. 5 a § 37 odst. 3 NGŘ č. 33/2019)', '§ 18 zákona č. 555/1992 Sb.; § 30 odst. 5 a § 37 odst. 3 NGŘ č. 33/2019', 'Použití zbraně – nestřežené pracoviště'),
  ('Služební příprava', 'Jak je podle NGŘ č. 16/2022 klasifikován svévolný odchod odsouzeného z nestřeženého pracoviště?', '["Závažná mimořádná událost podle § 5 písm. a)", "Závažná mimořádná událost podle § 5 písm. e) NGŘ", "Kázeňský přestupek bez hlášení události", "Ostatní mimořádná událost podle § 6 písm. e)"]'::jsonb, 3, 'Odchod z nestřeženého pracoviště je podle § 6 písm. e) NGŘ č. 16/2022 ostatní mimořádnou událostí, nikoli útěkem; věznice ji podle § 7 hlásí stálé službě GŘ a dozorovému státnímu zástupci. (Právní úprava: § 6 písm. e) a § 7 NGŘ č. 16/2022)', '§ 6 písm. e) a § 7 NGŘ č. 16/2022', 'Mimořádné události – odchod z pracoviště'),
  ('Služební příprava', 'Jak je podle NGŘ č. 16/2022 klasifikováno použití střelné zbraně příslušníkem?', '["Ostatní mimořádná událost podle § 6 písm. h)", "Závažná mimořádná událost podle § 5 písm. h)", "Běžná událost zapsaná jen do knihy", "Ostatní mimořádná událost podle § 6 písm. f) NGŘ"]'::jsonb, 1, 'Použití střelné zbraně je podle § 5 písm. h) NGŘ č. 16/2022 závažnou mimořádnou událostí; příslušník je navíc povinen je bezodkladně oznámit nadřízenému (§ 20 zákona č. 555/1992 Sb.). (Právní úprava: § 5 písm. h) NGŘ č. 16/2022)', '§ 5 písm. h) NGŘ č. 16/2022', 'Mimořádné události – použití zbraně'),
  ('Penologie', 'U kterých odsouzených probíhá diagnostika nástrojem SARPO v nástupním oddíle kmenové věznice?', '["U všech odsouzených bez ohledu na délku trestu", "Jen u odsouzených s trestem nad pět let", "U odsouzených s trestem delším než tři měsíce", "Jen u recidivistů a mladistvých"]'::jsonb, 2, 'Diagnostika prostřednictvím SARPO probíhá v nástupním oddíle kmenové věznice (zpravidla 2 týdny) u odsouzených s trestem delším než tři měsíce; jejím výsledkem je komplexní zpráva podle § 41 zákona č. 169/1999 Sb. (Právní úprava: Penologie a KSSVO (2025), s. 16 až 17; § 41 zákona č. 169/1999 Sb.)', 'Penologie a KSSVO (2025), s. 16 až 17; § 41 zákona č. 169/1999 Sb.', 'SARPO – nástupní oddíl'),
  ('Právo', 'Jaký je nejvyšší rozsah kázeňského trestu snížení základního tarifu příslušníka podle zákona č. 361/2003 Sb.?', '["Až o 25 % na dobu nejvýše 3 měsíců", "Až o 10 % nejvýše na 6 měsíců", "Až o 50 % na dobu nejvýše 1 měsíce", "Až o 15 % na dobu nejvýše 12 kalendářních měsíců"]'::jsonb, 0, 'Podle § 51 zákona č. 361/2003 Sb. lze uložit snížení základního tarifu až o 25 procent na dobu nejvýše 3 měsíců. (Právní úprava: § 51 odst. 1 zákona č. 361/2003 Sb.)', '§ 51 odst. 1 zákona č. 361/2003 Sb.', 'Služební poměr – kázeňské tresty'),
  ('Zbraně', 'Kdy lze u pistole CZ 75 B zajistit zbraň manuální pojistkou?', '["Jen při vypuštěném kohoutu", "Jen při plně napnutém kohoutu", "Jen s vyjmutým zásobníkem", "Kdykoli bez ohledu na polohu kohoutu"]'::jsonb, 1, 'Manuální pojistku ovládá střelec přesunutím nahoru, až se zakryje červená značka; zajistit lze jen při napnutém kohoutu a blokován je spoušťový mechanismus i závěr. (Právní úprava: učební text Speciální příprava (Střelecká teorie), s. 1 až 6)', 'učební text Speciální příprava (Střelecká teorie), s. 1 až 6', 'Pistole CZ 75 B'),
  ('Služební příprava', 'Jakými prostředky jsou podle učebního textu Strážní služba vyzbrojeni strážní při předvádění vězněných osob?', '["Pistolí CZ 75 B, služebními pouty a předváděcími řetízky", "Obuškem, pouty, elektrickým paralyzérem a služebním psem na vodítku", "Předváděcími řetízky, pouty, slzotvorným prostředkem a obuškem", "Pouty s poutacím opaskem, slzotvorným prostředkem a pistolí"]'::jsonb, 2, 'Strážní jsou při předvádění vyzbrojeni předváděcími řetízky, pouty, slzotvorným prostředkem a obuškem; střelná zbraň ani služební pes do této výzbroje nepatří. (Právní úprava: učební text Strážní služba (Kupec), s. 3; § 86 NGŘ č. 33/2019)', 'učební text Strážní služba (Kupec), s. 3; § 86 NGŘ č. 33/2019', 'Strážní služba – předvádění'),
  ('Penologie', 'Kdo podle § 14 zákona č. 169/1999 Sb. stanoví vnitřní řád věznice pro odsouzené?', '["Ředitel věznice se souhlasem generálního ředitelství VS", "Generální ředitel Vězeňské služby na návrh ředitele věznice", "Ministr spravedlnosti po projednání s generálním ředitelem", "Vedoucí oddělení výkonu trestu se souhlasem ředitele"]'::jsonb, 0, 'Vnitřní řád věznice pro odsouzené stanoví její ředitel se souhlasem generálního ředitelství Vězeňské služby; jeho přílohou je časový rozvrh dne. (Právní úprava: § 14 zákona č. 169/1999 Sb.)', '§ 14 zákona č. 169/1999 Sb.', 'Vnitřní řád věznice'),
  ('Služební příprava', 'Kdy se u obviněného podle § 96 odst. 1 písm. i) NGŘ č. 33/2019 nemusí provést preventivní osobní prohlídka při vyvedení z cely a před umístěním zpět?', '["Jde-li o krátké předvedení do třiceti minut v rámci téhož oddělení", "Byl-li předveden jen k lékaři nebo k obhájci uvnitř objektu věznice nebo ústavu", "Souhlasí-li s upuštěním od prohlídky inspektor dozorčí služby", "Byl-li po celou dobu předvádění bezprostředně střežen příslušníkem"]'::jsonb, 3, 'U obviněného se preventivní osobní prohlídka provádí při každém vyvedení z cely a před umístěním zpět, nebyl-li po celou dobu předvádění bezprostředně střežen příslušníkem dozorčí služby nebo vězeňské stráže. (Právní úprava: § 96 odst. 1 písm. i) NGŘ č. 33/2019)', '§ 96 odst. 1 písm. i) NGŘ č. 33/2019', 'Prohlídky – preventivní osobní prohlídka'),
  ('Služební příprava', 'Z jaké pozice provádí příslušník preventivní osobní prohlídku vězněné osoby podle učebního textu Prohlídky?', '["Zepředu, aby měl stále přehled o rukou prohlíženého", "Zásadně odzadu, nikdy nestojí před prohlíženým", "Z boku, střídavě z levé a z pravé strany", "Z libovolné strany podle dispozice místnosti"]'::jsonb, 1, 'Prohlídka se provádí zásadně odzadu a příslušník nikdy nestojí před prohlíženým; prohlížený je rozkročen a rozpažen, případně opřen o zeď nebo katr. (Právní úprava: učební text PROHLÍDKY, s. 4–8; § 96 NGŘ č. 33/2019)', 'učební text PROHLÍDKY, s. 4–8; § 96 NGŘ č. 33/2019', 'Prohlídky – preventivní osobní prohlídka'),
  ('Služební příprava', 'Kolik vozidel se podle NGŘ č. 33/2019 a Metodiky vstupů a vjezdu zpravidla vpouští současně do vjezdového koše?', '["Nejvýše dvě vozidla současně, je-li u vjezdu přítomen VISS", "Libovolný počet, pokud se vejdou mezi obě brány", "Nejvýše jedno vozidlo, s výjimkou vozidel VS ČR a IZS", "Jedno vozidlo, a to bez jakékoli výjimky"]'::jsonb, 2, 'Do vjezdového koše se vpustí zpravidla nejvýše jedno vozidlo; výjimkou jsou vozidla VS ČR nebo integrovaného záchranného systému. (Právní úprava: § 80 NGŘ č. 33/2019; Metodika vstupy a vjezd do objektu)', '§ 80 NGŘ č. 33/2019; Metodika vstupy a vjezd do objektu', 'Strážní služba – vjezd vozidel'),
  ('Služební příprava', 'Kdo smí při vjezdu civilního zásobovacího vozidla projet vjezdovým košem spolu s vozidlem?', '["Pouze řidič; závozník vstupuje hlavním vchodem", "Řidič i závozník, pokud oba mají platný doklad", "Všechny osoby uvedené v dodacím listu", "Řidič a závozník v doprovodu strážného ve vozidle"]'::jsonb, 0, 'Při vjezdu civilního vozidla se do vjezdového koše vpouští pouze řidič; další osoby, například závozník, vstupují hlavním vchodem, a to jen je-li to nezbytné k nakládání nebo vykládání. (Právní úprava: § 80 NGŘ č. 33/2019; Metodika vstupy a vjezd do objektu)', '§ 80 NGŘ č. 33/2019; Metodika vstupy a vjezd do objektu', 'Strážní služba – vjezd vozidel'),
  ('Služební příprava', 'Jak postupuje strážný doprovodu, mají-li odsouzení naložit na vozidlo pevně uzavřené bedny, které nebyly kontrolovány před naplněním?', '["Naložení povolí a bedny nechá zkontrolovat na vjezdu", "Bedny nechá zaplombovat a zapíše je do knihy", "Naložení povolí, podepíše-li řidič prohlášení o obsahu", "Nakládání nepřipustí, dokud obsah beden nezkontroluje"]'::jsonb, 3, 'Strážný při doprovodu a střežení vozidel nesmí připustit nakládání nepřehledného a těžko kontrolovatelného materiálu, například sudů nebo uzavřených beden, pokud nebyly kontrolovány před jejich naplněním. (Právní úprava: § 82 odst. 1 písm. d) NGŘ č. 33/2019)', '§ 82 odst. 1 písm. d) NGŘ č. 33/2019', 'Strážní služba – doprovod a střežení vozidel'),
  ('Služební příprava', 'Jak postupuje strážný u vjezdu, zjistí-li, že na odjíždějící vozidlo byl uvnitř objektu naložen materiál bez přítomnosti strážného?', '["Vozidlo propustí a událost zapíše do VIS", "Vozidlo nepropustí a okamžitě vyrozumí VISS", "Vozidlo propustí, pokud rentgen nic neodhalí", "Vozidlo vrátí na pracoviště k novému naložení"]'::jsonb, 1, 'Zjistí-li strážný u vjezdu, že materiál byl naložen bez přítomnosti strážného, vozidlo nepropustí a okamžitě vyrozumí vrchního inspektora strážní služby. (Právní úprava: § 80 odst. 2 písm. n) NGŘ č. 33/2019)', '§ 80 odst. 2 písm. n) NGŘ č. 33/2019', 'Strážní služba – vjezd vozidel'),
  ('Služební příprava', 'Kdo a jakým aktem stanoví podle § 30 odst. 6 NGŘ č. 33/2019 Zásady vnitřní bezpečnosti věznice?', '["Generální ředitel VS ČR svým pokynem", "Vedoucí oddělení VJS rozkazem", "Ředitel věznice svým nařízením", "Ministr spravedlnosti prováděcí vyhláškou"]'::jsonb, 2, 'K zajištění vnitřní bezpečnosti vydává ředitel věznice nařízení, kterým stanoví Zásady vnitřní bezpečnosti; návrh předkládá vedoucí oddělení vězeňské a justiční stráže a zásady jsou závazné pro všechny příslušníky a zaměstnance věznice. (Právní úprava: § 30 odst. 6 NGŘ č. 33/2019)', '§ 30 odst. 6 NGŘ č. 33/2019', 'Zásady vnitřní bezpečnosti'),
  ('Právo', 'Jaká je promlčecí doba podle § 34 trestního zákoníku u trestného činu, jehož horní hranice trestní sazby odnětí svobody činí nejméně deset let?', '["Patnáct let", "Deset let", "Dvanáct let", "Dvacet pět let"]'::jsonb, 0, 'Promlčecí doba činí 30 let u činů s výjimečným trestem a vraždy, 15 let při horní hranici nejméně 10 let, 10 let při nejméně 5 letech, 5 let při nejméně 3 letech a 3 léta u ostatních činů. (Právní úprava: § 34 zákona č. 40/2009 Sb., trestní zákoník)', '§ 34 zákona č. 40/2009 Sb., trestní zákoník', 'Promlčení trestní odpovědnosti'),
  ('Zbraně', 'Jaký je podle učebního textu Speciální příprava účinný dostřel samopalu CZ Scorpion EVO 3 A1?', '["150 m", "2200 m", "50 m", "200 m"]'::jsonb, 3, 'Účinný dostřel samopalu CZ Scorpion EVO 3 A1 je 200 m; 2200 m je jeho maximální dostřel. (Právní úprava: učební text Speciální příprava, kapitola CZ Scorpion EVO 3 A1)', 'učební text Speciální příprava, kapitola CZ Scorpion EVO 3 A1', 'Samopal CZ Scorpion EVO 3 A1'),
  ('Zbraně', 'Kolik nábojů tvoří podle učebního textu plný palebný průměr samopalu CZ Scorpion EVO 3 A1?', '["60 nábojů ve dvou zásobnících", "90 nábojů ve třech zásobnících", "120 nábojů ve čtyřech zásobnících", "30 nábojů v jednom zásobníku"]'::jsonb, 1, 'Plný palebný průměr samopalu CZ Scorpion EVO 3 A1 je 90 nábojů, tedy tři zásobníky po 30 nábojích. (Právní úprava: učební text Speciální příprava, kapitola CZ Scorpion EVO 3 A1)', 'učební text Speciální příprava, kapitola CZ Scorpion EVO 3 A1', 'Samopal CZ Scorpion EVO 3 A1'),
  ('Penologie', 'Pro které odsouzené je podle studijního materiálu Penologie vhodné pracoviště s volným pohybem mimo věznici (VPMV)?', '["Pro odsouzené ve věznici se zvýšenou ostrahou", "Pro všechny odsouzené ve vysokém stupni zabezpečení", "Pro vybrané odsouzené v nízkém či středním stupni", "Pro obviněné s kladným hodnocením chování"]'::jsonb, 2, 'Pracoviště s volným pohybem mimo věznici je vhodné pro pečlivě vybrané odsouzené ve věznici s ostrahou zařazené v nízkém nebo středním stupni zabezpečení; obvinění mohou pracovat jen v prostoru věznice. (Právní úprava: Penologie a KSSVO (2025), kapitola 7.1 Druhy pracovišť; §§ 51–55 vyhlášky č. 345/1999 Sb.)', 'Penologie a KSSVO (2025), kapitola 7.1 Druhy pracovišť; §§ 51–55 vyhlášky č. 345/1999 Sb.', 'Druhy pracovišť odsouzených'),
  ('Služební příprava', 'V doprovodu koho mohou oprávněné osoby podle § 54 odst. 2 NGŘ č. 33/2019 kontrolovat strážní stanoviště v zakázaném pásmu?', '["Jen v doprovodu VISS, ISS nebo velitele eskorty", "Bez doprovodu, stačí předložit služební průkaz", "Jen v doprovodu ředitele věznice nebo jeho zástupce", "V doprovodu kteréhokoli příslušníka strážní směny"]'::jsonb, 0, 'Na stanoviště u hlavního vchodu a vnitřní stanoviště mohou kontrolující vstupovat i bez doprovodu, stanoviště v zakázaném pásmu však kontrolují jen v doprovodu VISS, ISS nebo velitele eskorty na střeženém pracovišti. (Právní úprava: § 54 odst. 2 NGŘ č. 33/2019)', '§ 54 odst. 2 NGŘ č. 33/2019', 'Kontrola strážních stanovišť'),
  ('Služební příprava', 'Kdo z uvedených je podle § 54 odst. 1 NGŘ č. 33/2019 oprávněn provádět kontrolu strážních stanovišť?', '["Vedoucí oddělení výkonu trestu dané věznice", "Inspektor dozorčí služby v denní službě", "Předseda senátu soudu, k němuž se eskortuje osoba", "Ředitel odboru vězeňské a justiční stráže GŘ"]'::jsonb, 3, 'Kontrolu mohou provádět ministr spravedlnosti a jím pověření, generální ředitel a náměstci, ředitel odboru vězeňské a justiční stráže GŘ, ředitel věznice a zástupci, VOVS a zástupci a osoby jimi určené. (Právní úprava: § 54 odst. 1 NGŘ č. 33/2019)', '§ 54 odst. 1 NGŘ č. 33/2019', 'Kontrola strážních stanovišť'),
  ('Služební příprava', 'Komu smí strážný při výkonu služby podle § 32 odst. 3 NGŘ č. 33/2019 vydat svou zbraň nebo zásobníky s náboji?', '["Pouze kontrolnímu orgánu generálního ředitelství", "Nikomu, a to ani osobám, jimž je podřízen", "Jen vrchnímu inspektorovi strážní služby", "Jen řediteli věznice nebo jeho zástupci"]'::jsonb, 1, 'Strážný při výkonu služby nesmí nikomu vydat svoji zbraň ani zásobníky s náboji, a to ani osobám, jimž je podřízen. (Právní úprava: § 32 odst. 3 NGŘ č. 33/2019)', '§ 32 odst. 3 NGŘ č. 33/2019', 'Strážní služba – zbraň na stanovišti'),
  ('Služební příprava', 'Kdo může podle § 32 odst. 4 NGŘ č. 33/2019 strážného vystřídat nebo odvolat ze stanoviště?', '["Kterýkoli kontrolující podle § 54", "Inspektor dozorčí služby nebo ředitel věznice", "Pouze VISS nebo inspektor strážní služby", "Jen vedoucí oddělení VJS nebo zástupce"]'::jsonb, 2, 'Strážný neopustí stanoviště, dokud nebude vystřídán nebo odvolán; vystřídat nebo odvolat jej může pouze vrchní inspektor strážní služby nebo inspektor strážní služby. (Právní úprava: § 32 odst. 4 a § 79 odst. 1 písm. c) NGŘ č. 33/2019)', '§ 32 odst. 4 a § 79 odst. 1 písm. c) NGŘ č. 33/2019', 'Strážní služba – střídání strážného'),
  ('Zbraně', 'Jak se podle § 19 NGŘ č. 33/2019 nabíjí služební zbraň před výkonem služby?', '["Zasune se zásobník, náboj do komory se nezasouvá, závěr zůstává vpředu", "Zasune se zásobník a natažením závěru se náboj zasune do komory", "Zásobník se nosí odděleně a do zbraně se vkládá až po příchodu na stanoviště", "Náboj se vloží do komory ručně a zasune se částečně plný zásobník"]'::jsonb, 0, 'Zbraň se nabíjí zasunutím zásobníku se stanoveným počtem nábojů, náboj se do nábojové komory nezasouvá, závěr zůstává v přední poloze a zbraň se zajistí. (Právní úprava: § 19 NGŘ č. 33/2019)', '§ 19 NGŘ č. 33/2019', 'Nabíjení a vybíjení zbraní'),
  ('Právo', 'Má stížnost proti usnesení o vzetí obviněného do vazby odkladný účinek?', '["Ano, stížnost má odkladný účinek vždy", "Ne, tato stížnost odkladný účinek nemá", "Ano, ale jen je-li podána obhájcem", "Ne, protože proti vazbě stížnost nelze podat"]'::jsonb, 1, 'Stížnost má odkladný účinek jen tam, kde to zákon výslovně stanoví; stížnost proti usnesení o vzetí do vazby odkladný účinek nemá, má však účinek devolutivní. (Právní úprava: § 141 a § 143 odst. 1 zákona č. 141/1961 Sb., trestní řád)', '§ 141 a § 143 odst. 1 zákona č. 141/1961 Sb., trestní řád', 'Opravné prostředky v trestním řízení'),
  ('Psychologie', 'Jak se podle učebního textu Psychologie nazývá stupeň odolnosti člověka vůči frustraci?', '["Stresová rezistence", "Emoční labilita", "Frustrační tolerance", "Adaptační kapacita jedince"]'::jsonb, 2, 'Stupeň odolnosti vůči frustraci se nazývá frustrační tolerance a je u každého člověka různý. (Právní úprava: Učební text Psychologie pro ZOP (2023), kapitola Náročné životní situace, s. 35–36)', 'Učební text Psychologie pro ZOP (2023), kapitola Náročné životní situace, s. 35–36', 'Náročné životní situace'),
  ('Penologie', 'Jak se naloží s balíčkem pro obviněného, jehož hmotnost překračuje povolených 5 kg, nebyl-li vrácen již při návštěvě?', '["Vrátí se odesilateli podle řádu výkonu vazby", "Předá se obviněnému a přebytek se uloží do úschovy", "Obsah se přebalí a předá v nejbližším termínu", "Zničí se jako věc zcela nepatrné hodnoty"]'::jsonb, 0, 'Balíček, který má vyšší než povolenou hmotnost, se vrátí odesilateli, pokud k vrácení nedošlo již při návštěvě; odesilatel se vyrozumí o rozsahu povolených věcí. (Právní úprava: § 48 odst. 3 vyhlášky č. 109/1994 Sb.; § 16 odst. 2 zákona č. 293/1993 Sb.)', '§ 48 odst. 3 vyhlášky č. 109/1994 Sb.; § 16 odst. 2 zákona č. 293/1993 Sb.', 'Balíčky obviněných'),
  ('Penologie', 'Může ředitel věznice u obviněného v koluzní vazbě umožnit návštěvu bez sluchové, případně zrakové kontroly?', '["Ano, se souhlasem státního zástupce", "Ano, jen jde-li o manželku", "Ano, trvá-li vazba déle než tři měsíce", "Ne, u koluzní vazby ji neumožní"]'::jsonb, 3, 'Návštěvu bez sluchové, popřípadě zrakové kontroly ředitel věznice u obviněného v koluzní vazbě neumožní; nelze u něj ani zprostředkovat návštěvu příbuzného, který je rovněž ve vazbě nebo výkonu trestu. (Právní úprava: § 44 odst. 6 a § 45 vyhlášky č. 109/1994 Sb.)', '§ 44 odst. 6 a § 45 vyhlášky č. 109/1994 Sb.', 'Návštěvy obviněných v koluzní vazbě'),
  ('Služební příprava', 'Kdo podle § 41 odst. 3 NGŘ č. 33/2019 rozhoduje o způsobu poutání eskortovaného při eskortě?', '["Velitel eskorty na základě chování eskortovaného", "VOVS, v jeho nepřítomnosti službu konající VISS", "Ředitel věznice na návrh vedoucího oddělení", "Soud, který eskortu nařídil"]'::jsonb, 1, 'O způsobu poutání při eskortě rozhoduje po individuálním posouzení vedoucí oddělení vězeňské a justiční stráže, v jeho nepřítomnosti službu konající VISS; způsob se vyznačí na propustce nebo eskortním příkazu. Velitel eskorty může v průběhu eskorty přiložit další DP. (Právní úprava: § 41 odst. 3 NGŘ č. 33/2019)', '§ 41 odst. 3 NGŘ č. 33/2019', 'Donucovací prostředky – eskorta'),
  ('Služební příprava', 'Co se podle § 41 odst. 4 NGŘ č. 33/2019 vždy přikládá eskortovanému při předvádění mimo věznici, jsou-li mu přiložena pouta?', '["Poutací opasek", "Nožní řetízková pouta", "Předváděcí řetízky", "Poutací popruhy"]'::jsonb, 2, 'Eskortovanému se při předvádění mimo věznici v případě přiložení pout vždy přikládají předváděcí řetízky. (Právní úprava: § 41 odst. 4 NGŘ č. 33/2019)', '§ 41 odst. 4 NGŘ č. 33/2019', 'Donucovací prostředky – eskorta'),
  ('Služební příprava', 'Na jak dlouho nejdéle lze podle § 17 odst. 5 zákona č. 555/1992 Sb. omezit volný pohyb osoby připoutáním k vhodnému předmětu?', '["Nejdéle na 2 hodiny", "Nejdéle na 1 hodinu", "Nejvýše na 24 h", "Nejdéle na dobu 6 hodin"]'::jsonb, 0, 'Připoutání k vhodnému předmětu, zejména pouty, lze u osoby, která fyzicky napadá, ohrožuje vlastní život, poškozuje majetek nebo se pokusí o útěk, provést nejdéle na 2 hodiny. (Právní úprava: § 17 odst. 5 zákona č. 555/1992 Sb.)', '§ 17 odst. 5 zákona č. 555/1992 Sb.', 'Donucovací prostředky – připoutání'),
  ('Služební příprava', 'Za čí přítomnosti se podle § 99 odst. 6 NGŘ č. 33/2019 provádí případná osobní prohlídka dítěte vstupujícího do věznice?', '["Za přítomnosti vrchního dozorce", "Vždy za přítomnosti zákonného zástupce", "Za přítomnosti dvou příslušníků VS", "Za přítomnosti sociálního pracovníka věznice"]'::jsonb, 1, 'Kontrola dítěte se provádí přiměřeně věku, komunikace směřuje k doprovázející osobě a osobní prohlídka dítěte se provádí vždy za přítomnosti jeho zákonného zástupce. (Právní úprava: § 99 odst. 6 NGŘ č. 33/2019; Metodika vstupy a vjezd do objektu, část 5)', '§ 99 odst. 6 NGŘ č. 33/2019; Metodika vstupy a vjezd do objektu, část 5', 'Kontrola osob při vstupu – děti'),
  ('Penologie', 'Jak často se podle vyhlášky č. 345/1999 Sb. nejméně provádí dohled nad odsouzenými z oddělení s vysokým stupněm zabezpečení na nestřeženém pracovišti?', '["Nejméně jedenkrát za 45 minut", "Nejméně jedenkrát týdně", "Nejméně jedenkrát za 2 hodiny", "Nejméně jedenkrát za každých 30 minut"]'::jsonb, 0, 'Dohled se provádí u nízkého stupně zabezpečení nejméně jednou týdně, u středního nejméně jednou za hodinu a u vysokého nejméně jednou za 45 minut. (Právní úprava: § 51 odst. 2, § 52 odst. 3 a § 53 odst. 5 vyhlášky č. 345/1999 Sb.)', '§ 51 odst. 2, § 52 odst. 3 a § 53 odst. 5 vyhlášky č. 345/1999 Sb.', 'Nestřežené pracoviště – intervaly dohledu'),
  ('Služební příprava', 'Jak se podle § 37 odst. 3 NGŘ č. 33/2019 posuzuje převoz vězněných osob na nestřežená pracoviště?', '["Jako zvláštní eskorta vězněných osob", "Jako hromadná eskorta osob", "Jako eskorta se sníženým počtem strážných", "Nepovažuje se vůbec za eskortu"]'::jsonb, 3, 'Převoz vězněných osob na nestřežená pracoviště se nepovažuje za eskortu; dozorce postupuje podle svých povinností na nestřeženém pracovišti a pokynů nadřízených. (Právní úprava: § 37 odst. 3 NGŘ č. 33/2019)', '§ 37 odst. 3 NGŘ č. 33/2019', 'Nestřežené pracoviště – převoz'),
  ('Služební příprava', 'Z jakých dvou částí se podle NGŘ č. 33/2019 skládá rozdílení strážní a eskortní směny?', '["Z nástupu směny a ze střídání strážných na stanovištích", "Z kontroly výzbroje a z nabíjení zbraní", "Z přípravy k výkonu služby a z vlastního rozdílení", "Z prověrky znalostí a z vyhlášení rozkazu"]'::jsonb, 2, 'Rozdílení se dělí na přípravu k výkonu služby (§ 49) a vlastní rozdílení směny (§ 50), které končí vyhlášením denního rozkazu vedoucího oddělení. (Právní úprava: § 48 až § 50 NGŘ č. 33/2019)', '§ 48 až § 50 NGŘ č. 33/2019', 'Rozdílení směny'),
  ('Služební příprava', 'Čím podle § 50 NGŘ č. 33/2019 končí rozdílení směny?', '["Vyhlášením denního rozkazu vedoucího oddělení", "Nabitím zbraní na vybíjecím místě", "Hlášením odpovědného příslušníka VISS", "Převzetím všech stanovišť od předchozí strážní směny"]'::jsonb, 0, 'Vyhlášením denního rozkazu vedoucího oddělení s určením strážných na stanoviště a eskorty rozdílení končí; směna pak odchází k nabíjení zbraní a střídání stanovišť. (Právní úprava: § 50 odst. 1 písm. e) a odst. 2 NGŘ č. 33/2019)', '§ 50 odst. 1 písm. e) a odst. 2 NGŘ č. 33/2019', 'Rozdílení směny'),
  ('Vězeňská administrativa', 'Na jakém tiskopisu se zpracovává Záznam o odnětí věci podle § 12 odst. 1 zákona č. 555/1992 Sb.?', '["Na tiskopisu přílohy č. 9 NGŘ č. 41/2024", "Na tiskopisu přílohy č. 4 NGŘ č. 41/2024", "Na tiskopisu přílohy č. 6 k NGŘ č. 28/2018", "Na tiskopise přílohy č. 1 NGŘ č. 16/22"]'::jsonb, 0, 'Záznam o odnětí věci je přílohou č. 9 NGŘ č. 41/2024 a slouží zároveň jako důkazní prostředek v kázeňském řízení; příloha č. 4 je Záznam o kázeňském přestupku. (Právní úprava: § 37 odst. 2 NGŘ č. 41/2024, příloha č. 9)', '§ 37 odst. 2 NGŘ č. 41/2024, příloha č. 9', 'Záznam o odnětí věci'),
  ('Vězeňská administrativa', 'Kdo podepíše Záznam o odnětí věci, nelze-li určit, kdo je vlastníkem věci nebo kdo ji prokazatelně používal?', '["Příslušník, který věc odňal", "Vychovatel oddílu", "Vrchní dozorce oddělení", "Jiný přítomný odsouzený"]'::jsonb, 3, 'Nelze-li určit vlastníka věci nebo toho, kdo ji prokazatelně používal, podepíše záznam jiný přítomný odsouzený; odmítnutí podpisu se v záznamu vždy vyznačí. (Právní úprava: příloha č. 9 NGŘ č. 41/2024; učební text Prohlídky, Postup při odnětí věci, s. 10–11)', 'příloha č. 9 NGŘ č. 41/2024; učební text Prohlídky, Postup při odnětí věci, s. 10–11', 'Záznam o odnětí věci'),
  ('Služební příprava', 'Kdo schvaluje roční Plán dílčích a technických prohlídek věznice?', '["Ředitel věznice osobně", "První zástupce ředitele věznice", "Vedoucí oddělení VJS věznice", "Vrchní inspektor strážní služby VISS"]'::jsonb, 1, 'Dílčí a technické prohlídky se provádějí podle ročního Plánu dílčích a technických prohlídek, který schvaluje první zástupce ředitele věznice. (Právní úprava: § 90 odst. 1 a § 89 NGŘ č. 33/2019; učební text Prohlídky, s. 1–2)', '§ 90 odst. 1 a § 89 NGŘ č. 33/2019; učební text Prohlídky, s. 1–2', 'Dílčí a technické prohlídky'),
  ('Služební příprava', 'Jak je podle § 6 písm. g) NGŘ č. 16/2022 kvalifikován nález mobilního telefonu nebo SIM karty v objektu Vězeňské služby?', '["Jako kázeňská věc bez hlášení", "Jako závažná mimořádná událost", "Jako ostatní mimořádná událost", "Jako bezpečnostní incident III. stupně"]'::jsonb, 2, 'Nález nebo zneužití mobilního telefonu, SIM karty nebo jiného komunikačního či záznamového zařízení je ostatní mimořádnou událostí, která podléhá hlásné službě. (Právní úprava: § 6 písm. g) NGŘ č. 16/2022)', '§ 6 písm. g) NGŘ č. 16/2022', 'Mimořádné události'),
  ('Penologie', 'V jakém případě se podle § 41 zákona č. 169/1999 Sb. program zacházení pro odsouzeného nezpracovává?', '["Má-li vykonat trest nebo jeho zbytek do 3 měsíců", "Je-li zařazen do věznice se zvýšenou ostrahou", "Odmítne-li s programem vyslovit písemný souhlas", "Je-li starší šedesáti let a nemůže ze zdravotních důvodů pracovat"]'::jsonb, 0, 'Program zacházení se nezpracovává, má-li odsouzený vykonat trest nebo jeho zbytek ve výměře nepřesahující 3 měsíce. (Právní úprava: § 41 zákona č. 169/1999 Sb.)', '§ 41 zákona č. 169/1999 Sb.', 'Program zacházení'),
  ('Penologie', 'Do jakého programu se podle § 37 vyhlášky č. 345/1999 Sb. zařadí odsouzený, který odmítne přijetí programu zacházení stvrdit podpisem?', '["Do programu minimálního zacházení", "Do programu základního motivačního zacházení", "Do programu speciálního zacházení", "Do programu výstupního zacházení s odsouzenými"]'::jsonb, 1, 'Odsouzený, který odmítne přijetí programu stvrdit podpisem, se zařadí do programu základního motivačního zacházení. (Právní úprava: § 37 vyhlášky č. 345/1999 Sb.)', '§ 37 vyhlášky č. 345/1999 Sb.', 'Program zacházení'),
  ('Právo', 'V jaké lhůtě zasílá policejní orgán státnímu zástupci opis záznamu o zahájení úkonů trestního řízení?', '["Do 24 hodin", "Do dvou týdnů", "Do 48 hodin", "Do 3 dnů"]'::jsonb, 2, 'O zahájení úkonů trestního řízení sepíše policejní orgán neprodleně záznam, jehož opis zašle do 48 hodin státnímu zástupci. (Právní úprava: § 158 odst. 3 zákona č. 141/1961 Sb., trestní řád)', '§ 158 odst. 3 zákona č. 141/1961 Sb., trestní řád', 'Přípravné řízení'),
  ('Služební příprava', 'Jaký doklad se podle § 41 odst. 6 NGŘ č. 33/2019 vyhotovuje místo eskortního příkazu při eskortě za jiným účelem než k umístění nebo přemístění (např. k soudu)?', '["Propustka k eskortě", "Eskortní karta", "Příkaz k předvedení vězně", "Předvolání soudu"]'::jsonb, 0, 'Eskortní příkaz se vyhotovuje při umístění nebo přemístění vězněné osoby; při eskortě za jiným účelem, např. k soudu, se místo něj vyhotovuje propustka, k níž se připojuje písemná žádost soudu. (Právní úprava: § 41 odst. 6 NGŘ č. 33/2019)', '§ 41 odst. 6 NGŘ č. 33/2019', 'Eskorta k soudu – dokumentace'),
  ('Služební příprava', 'Kde je uložena Kniha hlášení velitele eskorty o průběhu služby (skl. č. VS 317) používaná při eskortách k soudu?', '["Na operačním středisku věznice", "Ve vozidle eskorty", "U vrchního inspektora JS", "V eskortní místnosti soudu"]'::jsonb, 3, 'Kniha hlášení velitele eskorty (skl. č. VS 317) je uložena v eskortní místnosti soudu; velitel eskorty do ní zapisuje mj. čas příjezdu a odjezdu, průběh jednání a technickou prohlídku eskortní místnosti. (Právní úprava: § 73 odst. 1 písm. q) NGŘ č. 33/2019)', '§ 73 odst. 1 písm. q) NGŘ č. 33/2019', 'Eskorta k soudu – dokumentace'),
  ('Právo', 'Jaká je podle § 68 odst. 2 trestního řádu hranice horní trestní sazby úmyslného trestného činu, do níž (nejsou-li dány výjimky) nelze obviněného vzít do vazby?', '["Horní hranice nepřevyšující jeden rok", "Horní hranice nepřevyšující pět let", "Horní hranice nepřevyšující dvě léta", "Horní hranice nepřevyšující tři léta"]'::jsonb, 2, 'Podle § 68 odst. 2 TŘ nelze vzít do vazby obviněného stíhaného pro úmyslný trestný čin s horní hranicí nepřevyšující dvě léta; tři léta jsou hranicí u nedbalostních trestných činů. (Právní úprava: § 68 odst. 2 zákona č. 141/1961 Sb.)', '§ 68 odst. 2 zákona č. 141/1961 Sb.', 'Vazba – podmínky'),
  ('Právo', 'Který soud rozhoduje o odvolání proti rozsudku okresního soudu?', '["Nejvyšší soud ČR", "Jiný senát okresního soudu", "Příslušný vrchní soud", "Nadřízený krajský soud"]'::jsonb, 3, 'O odvolání proti rozsudku okresního soudu rozhoduje nadřízený krajský soud; o odvolání proti rozsudku krajského soudu nadřízený vrchní soud. (Právní úprava: Učební text Právo (2022), Odvolací (opravné) řízení; zákon č. 141/1961 Sb.)', 'Učební text Právo (2022), Odvolací (opravné) řízení; zákon č. 141/1961 Sb.', 'Stadia trestního řízení'),
  ('Penologie', 'Jak často provádí dozorce prohlídku těla (zrakovou) u vězněné osoby zařazené v seznamu osob, u nichž se realizují opatření k předcházení násilí?', '["Jednou týdně", "Každý den", "Jednou za 14 dní", "Jednou měsíčně"]'::jsonb, 0, 'U vězněné osoby zařazené v seznamu se jednou týdně provádí prohlídka těla, aby se zjistilo, zda nenese zjevné stopy po fyzickém násilí; při podezření na násilí se provede neprodleně. (Právní úprava: NGŘ č. 24/2022; Penologie a KSSVO (2025), kapitola 9)', 'NGŘ č. 24/2022; Penologie a KSSVO (2025), kapitola 9', 'Předcházení násilí – NGŘ č. 24/2022'),
  ('Penologie', 'Kdo zajistí pořízení fotodokumentace stop fyzického násilí na těle vězněné osoby v mimopracovní době?', '["Inspektor dozorčí služby", "Vedoucí oddělení prevence a stížností", "Lékař zdravotnického střediska", "Vrchní inspektor strážní služby"]'::jsonb, 3, 'V pracovní době pořizuje fotodokumentaci pověřený orgán, v mimopracovní době ji zajistí vrchní inspektor strážní služby; pořizuje ji osoba stejného pohlaví. (Právní úprava: § 20 NGŘ č. 24/2022)', '§ 20 NGŘ č. 24/2022', 'Předcházení násilí – NGŘ č. 24/2022'),
  ('Penologie', 'Co se stane, odmítne-li odsouzený se stopami násilí lékařskou prohlídku, k níž byl předveden?', '["Prohlídka se provede proti jeho vůli", "Lékař s ním sepíše negativní reverz", "Dozorce sepíše jen služební záznam", "Věc se ihned předá Policii ČR"]'::jsonb, 1, 'Odmítne-li odsouzený lékařskou prohlídku, sepíše s ním lékař negativní reverz. Psychologem je vyšetřen i tehdy, když to odmítá. (Právní úprava: § 20 NGŘ č. 24/2022)', '§ 20 NGŘ č. 24/2022', 'Předcházení násilí – NGŘ č. 24/2022'),
  ('Psychologie', 'Jakému pásmu IQ odpovídá lehká mentální retardace (F70) podle 10. revize Mezinárodní klasifikace nemocí?', '["IQ 50 až 69", "IQ pod 20", "IQ 35 až 49", "IQ 70 až 100"]'::jsonb, 0, 'Lehká mentální retardace (F70) odpovídá IQ 50 až 69; s ní se ve věznicích setkáváme nejčastěji, osoby s těžšími stupni nebývají umisťovány do klasických věznic. (Právní úprava: Učební texty Pedagogika (2023), kapitola Mentální retardace)', 'Učební texty Pedagogika (2023), kapitola Mentální retardace', 'Mentální retardace'),
  ('Právo', 'Jak často musí soud nejméně přezkoumat, zda důvody zabezpečovací detence u dospělého chovance trvají?', '["Jednou za šest měsíců", "Jednou za dvacet čtyři měsíců", "Jednou za dvanáct měsíců", "Jednou za tři měsíce"]'::jsonb, 2, 'Soud nejméně jednou za dvanáct měsíců, u mladistvých jednou za šest měsíců, přezkoumá, zda důvody pro další pokračování zabezpečovací detence trvají. (Právní úprava: § 100 zákona č. 40/2009 Sb.)', '§ 100 zákona č. 40/2009 Sb.', 'Ochranná opatření – zabezpečovací detence'),
  ('Služební příprava', 'Jakou minimální šířku má vnitřní zakázané pásmo u ohradní zdi věznice?', '["2 metry", "12,5 metru", "3,5 metru", "4,5 metru"]'::jsonb, 3, 'Vnitřní zakázané pásmo má šířku minimálně 4,5 metru; vnější zakázané pásmo se zřizuje fakultativně o šířce 1 až 2 metry. (Právní úprava: Učební text Strážní služba (Kupec), s. 4–5; NGŘ č. 33/2019)', 'Učební text Strážní služba (Kupec), s. 4–5; NGŘ č. 33/2019', 'Strážní služba – střežený objekt'),
  ('Služební příprava', 'V jakých vzdálenostech od sebe se umísťují výstražné tabulky označující zakázané pásmo?', '["5 až 10 metrů", "40 až 50 metrů", "25 až 30 metrů", "80 až 100 metrů"]'::jsonb, 1, 'Zakázané pásmo se označuje výstražnými tabulkami vzdálenými od sebe 40 až 50 metrů. (Právní úprava: Učební text Strážní služba (Kupec), s. 4–5)', 'Učební text Strážní služba (Kupec), s. 4–5', 'Strážní služba – střežený objekt'),
  ('Služební příprava', 'Jak se strážný na strážní věži zachová při příchodu nadřízeného?', '["Opustí ochoz a podá hlášení u vstupu", "Podá hlášení radiostanicí na OS", "Nehlásí se a pokračuje ve střežení", "Hlásí se stanoveným hlášením nahlas"]'::jsonb, 2, 'Podle § 79 NGŘ č. 33/2019 se strážní na strážních věžích při příchodu nadřízených nehlásí; strážný nesmí odvracet pozornost od střežení. (Právní úprava: § 79 odst. 1 NGŘ č. 33/2019)', '§ 79 odst. 1 NGŘ č. 33/2019', 'Strážní služba – strážní věž'),
  ('Služební příprava', 'Jak se podle § 17 odst. 1 NGŘ č. 33/2019 nosí samopal nebo útočná puška při střežení z ochozu strážní věže?', '["V ponosu před tělem s odklopenou opěrkou", "Na zádech se sklopenou ramenní opěrkou a zajištěná", "Zavěšená na rameni hlavní dolů", "Odložená ve stojanu v kabině věže"]'::jsonb, 0, 'Samopal vz. 58, Scorpion EVO 3A1 i CZ 805 BREN A2 se při střežení z ochozu strážní věže nosí v ponosu před tělem s odklopenou ramenní opěrkou, připravené k případnému použití. (Právní úprava: § 17 odst. 1 NGŘ č. 33/2019)', '§ 17 odst. 1 NGŘ č. 33/2019', 'Strážní služba – strážní věž'),
  ('Služební příprava', 'Jak zákon č. 555/1992 Sb. posuzuje varovný výstřel strážného na strážní věži?', '["Jako použití střelné zbraně podle § 18", "Jako úkon, který nepodléhá úpravě", "Jako výzvu podle § 6 odst. 3 zákona", "Jako donucovací prostředek podle § 17"]'::jsonb, 3, 'Varovný výstřel je donucovacím prostředkem podle § 17 odst. 2 písm. m) zákona č. 555/1992 Sb., nikoli použitím střelné zbraně podle § 18; střílí se do bezpečného prostoru stanoveného strážní dokumentací. (Právní úprava: § 17 odst. 2 písm. m) zákona č. 555/1992 Sb.)', '§ 17 odst. 2 písm. m) zákona č. 555/1992 Sb.', 'Donucovací prostředky – varovný výstřel'),
  ('Služební příprava', 'Které jednání NENÍ podle § 17 odst. 5 zákona č. 555/1992 Sb. důvodem k omezení volného pohybu osoby připoutáním?', '["Fyzické napadání příslušníka nebo jiné osoby", "Úmyslné poškozování cizího majetku", "Verbální urážky bez fyzického útoku", "Pokus o útěk nebo ohrožení vlastního života"]'::jsonb, 2, 'Volný pohyb lze omezit osobě, která fyzicky napadá příslušníka nebo jinou osobu, ohrožuje vlastní život, poškozuje majetek nebo se pokusí o útěk. Samotné verbální napadení mezi tyto důvody nepatří. (Právní úprava: § 17 odst. 5 zákona č. 555/1992 Sb.)', '§ 17 odst. 5 zákona č. 555/1992 Sb.', 'Omezení volného pohybu osoby'),
  ('Právo', 'Co může předseda senátu podle § 66 odst. 2 trestního řádu učinit s obviněným ve vazbě, který se k soudu choval urážlivě?', '["Přenechat ho řediteli ke kázeňskému potrestání", "Prodloužit mu vazbu o dalších 30 dnů", "Uložit mu kázeňský trest samovazby", "Nařídit mu ihned přeložení do jiné vazební věznice"]'::jsonb, 0, 'Podle § 66 odst. 2 TŘ může předseda senátu přenechat obviněného, který se k soudu choval urážlivě, řediteli věznice ke kázeňskému potrestání; ředitel je povinen o výsledku vyrozumět soud. (Právní úprava: § 66 odst. 2 zákona č. 141/1961 Sb.)', '§ 66 odst. 2 zákona č. 141/1961 Sb.', 'Kázeňské řízení – obviněný u soudu'),
  ('Služební příprava', 'Jak se při služebním úkonu (bez odporu) zpravidla přikládají pouta?', '["S rukama za zády", "Za zády přes poutací opasek", "Na jednu ruku k předmětu", "S rukama vpředu před tělem"]'::jsonb, 3, 'Při služebním úkonu se pouta přikládají zpravidla s rukama vpředu; za zády převážně po služebním zákroku na dobu nezbytně nutnou nebo výjimečně u nebezpečné osoby. Při rukách za zády nelze použít předváděcí řetízky. (Právní úprava: Metodika poutání (Kupec), s. 6–11)', 'Metodika poutání (Kupec), s. 6–11', 'Poutání – taktické zásady'),
  ('Penologie', 'S kým smí obviněný ve vazbě z koluzních důvodů používat telefon podle § 13a zákona č. 293/1993 Sb.?', '["S osobou blízkou i s obhájcem", "Pouze se svým obhájcem", "Jen s osobou blízkou", "S nikým, telefon je vyloučen"]'::jsonb, 1, 'Obviněný má právo použít telefon ke kontaktu s osobou blízkou a s obhájcem nebo advokátem; u koluzní vazby jen s obhájcem. (Právní úprava: § 13a zákona č. 293/1993 Sb.)', '§ 13a zákona č. 293/1993 Sb.', 'Práva obviněného'),
  ('Penologie', 'Jak často musí být odsouzený v průběhu výkonu samovazby nebo celodenního umístění do uzavřeného oddílu prohlédnut lékařem?', '["Nejméně jednou týdně", "Nejméně jednou za měsíc", "Nejméně jednou za 14 dní", "Jen před nástupem"]'::jsonb, 0, 'K uložení těchto kázeňských trestů je nezbytné předchozí posouzení lékaře; před nástupem a nejméně jednou týdně v průběhu výkonu musí být odsouzený prohlédnut lékařem. (Právní úprava: § 49 odst. 1 a 2 zákona č. 169/1999 Sb.)', '§ 49 odst. 1 a 2 zákona č. 169/1999 Sb.', 'Kázeňské tresty – uzavřený oddíl'),
  ('Penologie', 'Kdy smí být odsouzený v uzavřeném oddílu umístěn do cely sám?', '["Kdykoli na jeho vlastní žádost podanou vedoucímu oddílu", "Vždy, jde-li o celodenní umístění do uzavřeného oddílu a samovazbu", "Při vážných bezpečnostních důvodech nebo bez dalšího odsouzeného", "Jen na základě rozhodnutí lékaře o jeho zdravotní způsobilosti"]'::jsonb, 2, 'Do cely může být odsouzený umístěn sám jen tehdy, jsou-li pro to vážné důvody bezpečnostní nebo nejsou-li ve výkonu tohoto kázeňského trestu současně alespoň dva odsouzení. (Právní úprava: § 70 NGŘ č. 02/2022)', '§ 70 NGŘ č. 02/2022', 'Kázeňské tresty – uzavřený oddíl'),
  ('Právo', 'Jaké hranice nesmí podle § 31 zákona č. 218/2003 Sb. překročit snížená trestní sazba odnětí svobody u mladistvého (mimo výjimku 5–10 let)?', '["Horní hranice 3 roky, dolní 6 měsíců", "Horní hranice deset let, dolní dva roky", "Horní hranice 8 let, dolní 2 roky", "Horní hranice pět let, dolní jeden rok"]'::jsonb, 3, 'Trestní sazby se u mladistvých snižují na polovinu, horní hranice nesmí převyšovat pět let a dolní jeden rok; při mimořádně závažném provinění lze uložit odnětí svobody na pět až deset let. (Právní úprava: § 31 zákona č. 218/2003 Sb.)', '§ 31 zákona č. 218/2003 Sb.', 'Odpovědnost mládeže'),
  ('Vězeňská administrativa', 'Co podle § 16 odst. 3 NGŘ č. 41/2024 nelze v popisu skutku záznamu o kázeňském přestupku nikdy uvést jako jediné porušení?', '["Porušení § 28 zákona o výkonu trestu", "Porušení vnitřního řádu věznice", "Porušení povinnosti plnit pokyny", "Porušení slušného chování"]'::jsonb, 1, 'Popis skutku musí vždy uvést, z jakého porušení zákonné povinnosti je odsouzený podezřelý; nikdy nelze uvést pouze porušení vnitřního řádu věznice. (Právní úprava: § 16 odst. 3 NGŘ č. 41/2024)', '§ 16 odst. 3 NGŘ č. 41/2024', 'Záznam o kázeňském přestupku'),
  ('Služební příprava', 'Jak se podle učebního textu Prohlídky provádí kontrola konečníku při důkladné osobní prohlídce?', '["Hmatem příslušníka v hygienických rukavicích", "Vždy výhradně lékařem na ošetřovně", "Detekčními prostředky bez dotyku nebo dřepy", "Vizuálně zepředu bez dalších úkonů"]'::jsonb, 2, 'Kontrola konečníku se provádí za využití detekčních prostředků, kterými se příslušník nedotýká těla, případně vykonáním několika hlubokých dřepů s rozkročenýma nohama; příslušník stojí za prohlíženým. (Právní úprava: § 95 NGŘ č. 33/2019; učební text Prohlídky (Kupec), s. 5–7)', '§ 95 NGŘ č. 33/2019; učební text Prohlídky (Kupec), s. 5–7', 'Důkladná osobní prohlídka'),
  ('Penologie', 'Které ustanovení zákona č. 169/1999 Sb. ukládá odsouzenému povinnost podrobit se preventivní vstupní lékařské prohlídce?', '["§ 28 odst. 2 písm. c)", "§ 16 odst. 5 a 6", "§ 46 odst. 1 písm. b)", "§ 36 odst. 1 a odst. 2"]'::jsonb, 0, 'Podle § 28 odst. 2 písm. c) je odsouzený povinen podrobit se preventivní vstupní, periodické, mimořádné a výstupní lékařské prohlídce v rozsahu určeném lékařem. § 16 odst. 6 upravuje jeho právo na zdravotní služby. (Právní úprava: § 28 odst. 2 písm. c) zákona č. 169/1999 Sb.)', '§ 28 odst. 2 písm. c) zákona č. 169/1999 Sb.', 'Zdravotní péče – povinnosti odsouzeného'),
  ('Penologie', 'Kdo zajišťuje výdej léků odsouzeným v případech, kdy jej neprovádí zdravotnický pracovník (a není pověřen jiný zaměstnanec)?', '["Dozorce oddílu odsouzeného", "Vychovatel oddílu odsouzeného", "Vrchní inspektor strážní služby", "Inspektor dozorčí služby OVT"]'::jsonb, 3, 'Výdej léků v intervalech a dávkách stanovených lékařem zajišťuje inspektor dozorčí služby oddělení výkonu trestu, u obviněných vrchní dozorce oddělení výkonu vazby. (Právní úprava: NGŘ č. 02/2022, § 24 odst. 2 písm. g), § 60 písm. s))', 'NGŘ č. 02/2022, § 24 odst. 2 písm. g), § 60 písm. s)', 'Zdravotní péče – výdej léků'),
  ('Služební příprava', 'Za jaké podmínky mohou být eskortovány nemocné vězněné osoby a těhotné ženy?', '["Jen se souhlasem ředitele věznice", "Jen se souhlasem lékaře", "Jen v sanitním vozidle", "Kdykoli, bez zvláštních podmínek"]'::jsonb, 1, 'Nemocné vězněné osoby a těhotné ženy mohou být eskortovány jen se souhlasem lékaře; stanovisko lékaře k omezení použití donucovacích prostředků je závazné. (Právní úprava: NGŘ č. 33/2019, § 41 odst. 12, § 43)', 'NGŘ č. 33/2019, § 41 odst. 12, § 43', 'Zdravotní eskorty'),
  ('Služební příprava', 'Kam se podle Metodiky poutání přikládá poutací opasek?', '["Do oblasti pasu nad pánev, nikdy přes zimní kabát", "Přes vrchní oděv, i přes zimní bundu", "Na hrudník pod paže přes vrchní oděv", "Na boky pod pánev přímo na kůži, pod veškerý spodní oděv"]'::jsonb, 0, 'Poutací opasek se přikládá zpravidla odzadu do oblasti pasu nad pánev, na co nejméně oděvních svršků, nikdy přes zimní kabát nebo bundu, a tak, aby nebyl příliš utažený ani volný. (Právní úprava: Metodika poutání (Kupec), s. 19–26)', 'Metodika poutání (Kupec), s. 19–26', 'Pouta s poutacím opaskem'),
  ('Vězeňská administrativa', 'Do čeho zapíše zaměstnanec s kázeňskou pravomocí výpověď svědka kázeňského přestupku (lékaře, sestry)?', '["Do tiskopisu podle přílohy č. 1 NGŘ č. 24/2022", "Do Záznamu o použití donucovacího prostředku", "Do Knihy předání a převzetí služby na stanovišti", "Do tiskopisu podle přílohy č. 5 NGŘ č. 41/2024"]'::jsonb, 3, 'Svědky zaměstnanec s kázeňskou pravomocí vyslechne a výpověď zapíše do tiskopisu podle přílohy č. 5 NGŘ č. 41/2024 nebo do záznamu o podání vysvětlení v systému ETŘ. (Právní úprava: § 19 NGŘ č. 41/2024, příloha č. 5)', '§ 19 NGŘ č. 41/2024, příloha č. 5', 'Záznam o kázeňském přestupku – důkazy'),
  ('Služební příprava', 'Kdo schvaluje „Informaci pro rozhodnutí předsedy senátu o ponechání donucovacích prostředků“ a v kolika výtiscích se vyhotovuje?', '["Vedoucí oddělení kmenové věznice, ve dvou výtiscích", "Ředitel věznice, ve třech výtiscích pro všechny strany", "Vrchní inspektor strážní služby, ve dvou výtiscích", "Velitel eskorty, v jednom výtisku pro soud"]'::jsonb, 0, 'Informace se zpracovává z údajů informačního systému a spisu, schvaluje ji vedoucí oddělení kmenové věznice a vyhotovuje se ve dvou výtiscích; obsahuje jen údaje nezbytné pro rozhodnutí předsedy senátu. (Právní úprava: § 42 odst. 5 až 7 NGŘ č. 33/2019)', '§ 42 odst. 5 až 7 NGŘ č. 33/2019', 'Eskorta k soudu'),
  ('Služební příprava', 'Kdo z členů eskorty jde při předvádění obviněného do jednací síně jako první před eskortovaným, je-li k předvádění využit?', '["Velitel celé eskorty", "Strážný řidič eskorty", "Příslušník justiční stráže u síně", "Psovod se služebním psem"]'::jsonb, 1, 'Obviněný se předvádí tak, aby byl po celou dobu střežen strážným; strážný řidič, je-li při předvádění využit, jde jako první před eskortovaným. (Právní úprava: § 73 odst. 1 NGŘ č. 33/2019; učební text Eskortní služba)', '§ 73 odst. 1 NGŘ č. 33/2019; učební text Eskortní služba', 'Eskorta k soudu'),
  ('Služební příprava', 'Předseda senátu rozhodne o sejmutí donucovacích prostředků obviněnému v jednací síni, ačkoli eskorta předložila informaci o rizicích. Jak velitel eskorty postupuje?', '["Vyžádá si nejprve písemný souhlas ředitele věznice", "Sejme prostředky ihned po příjezdu v eskortní místnosti", "Rozhodnutí respektuje a upozorní předsedu senátu na rizika", "Rozhodnutí odmítne, protože o poutání u soudu rozhoduje jen VOVS"]'::jsonb, 2, 'V otázkách souvisejících se soudním jednáním se velitel eskorty řídí pokyny předsedy senátu; informace je jen podkladem pro jeho rozhodnutí. Velitel na rizika upozorní a DP sejme až v jednací síni bezprostředně před zahájením jednání. (Právní úprava: § 73 odst. 1 písm. s) NGŘ č. 33/2019; učební text Eskortní služba)', '§ 73 odst. 1 písm. s) NGŘ č. 33/2019; učební text Eskortní služba', 'Eskorta k soudu'),
  ('Služební příprava', 'Předseda senátu rozhodl o sejmutí donucovacích prostředků v jednací síni. Co platí o poutání obviněného v přestávce jednání mimo jednací síň?', '["Obviněný se poutá jen tehdy, pokud o to požádá justiční stráž", "O poutání v přestávce rozhoduje vždy obhájce se souhlasem soudu", "Rozhodnutí předsedy senátu platí po celou dobu pobytu v budově soudu", "Opět se přiloží DP, mimo síň platí rozhodnutí vedoucího oddělení"]'::jsonb, 3, 'Rozhodnutí předsedy senátu se týká jen jednací síně; mimo ni platí rozhodnutí vedoucího oddělení o způsobu poutání, proto se před odvedením ze síně DP opět přikládají. (Právní úprava: § 41 odst. 3 a 4 a § 73 odst. 1 NGŘ č. 33/2019; učební text Eskortní služba)', '§ 41 odst. 3 a 4 a § 73 odst. 1 NGŘ č. 33/2019; učební text Eskortní služba', 'Eskorta k soudu'),
  ('Služební příprava', 'Soud rozhodne o propuštění obviněného přímo od soudu. Na základě čeho jej velitel eskorty propustí?', '["Na základě ústního pokynu předsedy senátu v jednací síni", "Pouze na základě písemného příkazu k propuštění", "Na základě vyhlášeného rozsudku a souhlasu obhájce", "Po telefonickém souhlasu operačního střediska"]'::jsonb, 1, 'Velitel eskorty ověří na oddělení správním možnost propuštění a propustí obviněného pouze na základě písemného příkazu k propuštění; po jeho obdržení se DP již nepřikládají. (Právní úprava: § 73 odst. 1 NGŘ č. 33/2019; učební text Eskortní služba)', '§ 73 odst. 1 NGŘ č. 33/2019; učební text Eskortní služba', 'Eskorta k soudu'),
  ('Služební příprava', 'Jak je podle NGŘ č. 33/2019 označen inspektor strážní služby (ISS)?', '["Bílou páskou na pravém rukávu", "Červenou páskou na levém rukávu", "Bílými šňůrami na levém rameni", "Žlutými šňůrami na pravém rameni"]'::jsonb, 2, 'Inspektor strážní služby je podřízen vrchnímu inspektorovi strážní služby, je nadřízený strážným ve směně a je označen na levém rameni bílými šňůrami. (Právní úprava: § 68 NGŘ č. 33/2019)', '§ 68 NGŘ č. 33/2019', 'Organizace vězeňské stráže'),
  ('Služební příprava', 'Komu je inspektor dozorčí služby (IDS) podřízen v mimopracovní době věznice?', '["Inspektorovi strážní služby operátorovi", "Řediteli věznice osobně", "Vedoucímu oddělení výkonu trestu", "Vrchnímu inspektorovi strážní služby"]'::jsonb, 3, 'IDS je přímo podřízen určenému zástupci vedoucího oddělení a nadřízen dozorcům ve směně; v mimopracovní době věznice je podřízen vrchnímu inspektorovi strážní služby. (Právní úprava: § 25 a § 60 NGŘ č. 02/2022)', '§ 25 a § 60 NGŘ č. 02/2022', 'Organizace dozorčí služby'),
  ('Služební příprava', 'Na koho se podle § 7 zákona č. 6/2002 Sb. nevztahuje povinnost podrobit se prohlídce při vstupu do budovy soudu, nestanoví-li předseda soudu jinak?', '["Na zaměstnance soudu a přísedící senátu", "Na státní zástupce, advokáty, notáře a soudní exekutory", "Na novináře s platným novinářským průkazem", "Na svědky, znalce a tlumočníky předvolané k soudnímu jednání"]'::jsonb, 1, 'Povinnost prohlídky se nevztahuje na státní zástupce, advokáty, notáře a soudní exekutory, nestanoví-li předseda soudu jinak; zákaz i povinnost se nevztahují na soudce a příslušníky ozbrojených sil a sborů ve službě. (Právní úprava: § 7 zákona č. 6/2002 Sb.; § 138 NGŘ č. 33/2019)', '§ 7 zákona č. 6/2002 Sb.; § 138 NGŘ č. 33/2019', 'Justiční stráž – vstup do soudu'),
  ('Služební příprava', 'Kdo rozhoduje o provedení osobní prohlídky osoby, u níž detektor kovů signalizuje kov?', '["Policie ČR přivolaná na místo", "Předseda senátu, k němuž osoba jde", "VIJS nebo velící příslušník JS", "Příslušník u rámu sám podle uvážení"]'::jsonb, 2, 'Signál detektoru kovu je důvodným podezřením, že osoba může mít nebezpečný předmět; o provedení osobní prohlídky rozhoduje VIJS nebo velící příslušník a provádí ji příslušník stejného pohlaví. (Právní úprava: § 150 odst. 4 NGŘ č. 33/2019)', '§ 150 odst. 4 NGŘ č. 33/2019', 'Justiční stráž – vstup do soudu'),
  ('Služební příprava', 'Jak postupuje justiční stráž, odmítne-li se osoba vstupující do soudu podrobit prohlídce?', '["Osobu na místě zadrží a předá ji Policii ČR", "Provede prohlídku i bez souhlasu osoby za použití hmatů a chvatů sebeobrany", "Osobu vpustí a informuje o tom předsedu senátu", "Nevpustí ji a informuje předsedu soudu či pověřeného zaměstnance"]'::jsonb, 3, 'Justiční stráž nevpustí do budovy osobu, která se prohlídce odmítne podrobit; informuje předsedu soudu, případně pověřeného zaměstnance, a řídí se jeho pokyny (u předvolané osoby informuje předsedu senátu nebo státního zástupce). (Právní úprava: Instrukce MS č. 8/2022, § 4; § 150 odst. 5 NGŘ č. 33/2019)', 'Instrukce MS č. 8/2022, § 4; § 150 odst. 5 NGŘ č. 33/2019', 'Justiční stráž – vstup do soudu'),
  ('Služební příprava', 'K soudu se dostaví podnapilá osoba předvolaná k jednání. Koho příslušník justiční stráže informuje?', '["Předsedu senátu nebo státního zástupce, který ji předvolal", "Dozorového státního zástupce krajského státního zastupitelství", "Vedoucího oddělení justiční stráže ve věznici", "Místně příslušnou městskou policii obce"]'::jsonb, 0, 'Jde-li o osobu předvolanou k jednání nebo k úkonu, příslušník informuje o podnapilosti předsedu příslušného senátu nebo státního zástupce, který ji předvolal, a řídí se jejich pokyny. (Právní úprava: Učební text Justiční stráž (Kupec), s. 3 a 9; Instrukce MS č. 8/2022, § 4)', 'Učební text Justiční stráž (Kupec), s. 3 a 9; Instrukce MS č. 8/2022, § 4', 'Justiční stráž – vstup do soudu'),
  ('Služební příprava', 'Jak postupuje příslušník justiční stráže při vizuální kontrole obsahu zavazadla?', '["Obsah sám vysype na stůl mimo dohled majitele zavazadla", "Do zavazadla nesahá a o vyjmutí obsahu požádá osobu", "Zavazadlo otevře a prohledá bez vědomí osoby", "Zavazadlo vždy zabaví až do odchodu osoby"]'::jsonb, 1, 'Do zavazadla příslušník zásadně nesahá, o vyjmutí obsahu vždy požádá kontrolovanou osobu; pohmatem jej smí zkontrolovat jen při trvajícím důvodném podezření, jinak vnesení nepovolí. (Právní úprava: § 148 NGŘ č. 33/2019; učební text Justiční stráž (Kupec), s. 10)', '§ 148 NGŘ č. 33/2019; učební text Justiční stráž (Kupec), s. 10', 'Justiční stráž – kontrola zavazadel'),
  ('Psychologie', 'Jaké rozpětí vzdálenosti odpovídá podle učebního textu Psychologie osobní zóně?', '["více než 3,5 m", "15 až 20 cm", "50 až 150 cm", "1,5 až 3,5 m"]'::jsonb, 2, 'Interpersonální zóny: intimní 15–20 cm, osobní 50–150 cm, sociální 1,5–3,5 m, veřejná více než 3,5 m. (Právní úprava: Učební text Psychologie pro ZOP (2023), kapitola Komunikace, s. 24–28)', 'Učební text Psychologie pro ZOP (2023), kapitola Komunikace, s. 24–28', 'Komunikace – proxemika'),
  ('Penologie', 'Které státní zastupitelství provádí dozor nad dodržováním právních předpisů při výkonu trestu odnětí svobody?', '["Okresní státní zastupitelství podle bydliště odsouzeného", "Nejvyšší státní zastupitelství se sídlem v Brně", "Vrchní státní zastupitelství podle sídla Generálního ředitelství VS ČR", "Krajské státní zastupitelství, v jehož obvodu se trest vykonává"]'::jsonb, 3, 'Dozor nad výkonem trestu provádí krajské státní zastupitelství, v jehož obvodu se trest vykonává; obdobný dozor nad výkonem vazby upravuje § 29 zákona č. 293/1993 Sb. (Právní úprava: § 78 zákona č. 169/1999 Sb.)', '§ 78 zákona č. 169/1999 Sb.', 'Dozor státního zástupce'),
  ('Služební příprava', 'Které prostředky nelze podle § 19 odst. 1 písm. b) zákona č. 555/1992 Sb. použít proti ženě, není-li splněna zákonná výjimka?', '["Obušek, vodní stříkač a vytlačování štítem nebo vozidlem", "Hmaty a chvaty, pouta a hrozbu střelnou zbraní", "Pouta, poutací popruhy a slzotvorný prostředek", "Služebního psa, elektrický prostředek a střelnou zbraň"]'::jsonb, 3, 'Proti ženě nelze použít služebního psa, elektrický nebo jiný obdobně dočasně zneschopňující prostředek a střelnou zbraň; neplatí to, pokud její útok bezprostředně ohrožuje život nebo zdraví a nebezpečí nelze odvrátit jinak, nebo při zamezení útěku podle § 18 odst. 1 písm. c). (Právní úprava: § 19 odst. 1 písm. b) zákona č. 555/1992 Sb.)', '§ 19 odst. 1 písm. b) zákona č. 555/1992 Sb.', 'Omezení donucovacích prostředků'),
  ('Služební příprava', 'Kdy smí justiční stráž provést služební zákrok bez pokynu předsedy senátu nebo jiné oprávněné osoby?', '["Jen nesnese-li zákrok odkladu a pokynu nelze dosáhnout", "Jen se souhlasem VIJS vydaným předem písemně", "Nikdy, bez pokynu nesmí zakročit v žádném případě", "Kdykoli, kdy to podle své úvahy uzná za vhodné velitel eskorty"]'::jsonb, 0, 'Bez pokynu oprávněné osoby provede justiční stráž služební zákrok jen tehdy, jestliže zákrok nesnese odkladu a pokynu oprávněné osoby nelze dosáhnout. (Právní úprava: § 22 odst. 6 zákona č. 555/1992 Sb.)', '§ 22 odst. 6 zákona č. 555/1992 Sb.', 'Justiční stráž – soudní jednání'),
  ('Služební příprava', 'Kdo zajišťuje při vyklízení jednací síně komunikaci s veřejností a výzvy?', '["Každý příslušník vyzývá osoby samostatně ve svém úseku", "Vždy jeden příslušník, ostatní plní jeho pokyny", "Předseda senátu osobně ze svého místa", "Velitel eskorty, který střeží obžalovaného"]'::jsonb, 1, 'Komunikaci s veřejností a výzvy zajišťuje vždy jeden příslušník, ostatní plní jeho pokyny; přítomné upozorní, že při neuposlechnutí bude použito donucovacích prostředků. (Právní úprava: § 142 NGŘ č. 33/2019)', '§ 142 NGŘ č. 33/2019', 'Justiční stráž – vyklizení síně'),
  ('Služební příprava', 'Kdo požádá o součinnost Policii ČR, nelze-li vyklizení jednací síně zvládnout vlastními silami?', '["Kterýkoli přítomný zaměstnanec soudu", "Předseda senátu prostřednictvím podatelny", "Vrchní inspektor justiční stráže (VIJS)", "Velitel eskorty vězeňské stráže"]'::jsonb, 2, 'Nelze-li situaci zvládnout vlastními silami, požádá VIJS o součinnost policii, popřípadě místně příslušnou městskou policii. (Právní úprava: § 142 odst. 3 NGŘ č. 33/2019)', '§ 142 odst. 3 NGŘ č. 33/2019', 'Justiční stráž – vyklizení síně'),
  ('Právo', 'Jakou formou rozhoduje soud o vyloučení veřejnosti z hlavního líčení?', '["Pokynem vrchního inspektora justiční stráže", "Opatřením předsedy soudu mimo jednání", "Rozsudkem vyhlášeným v jednací síni", "Usnesením podle § 200 trestního řádu"]'::jsonb, 3, 'O vyloučení veřejnosti rozhoduje soud usnesením podle § 200 trestního řádu; osoby rušící pořádek může předseda senátu vykázat podle § 204 odst. 1. (Právní úprava: § 200 a § 204 zákona č. 141/1961 Sb.)', '§ 200 a § 204 zákona č. 141/1961 Sb.', 'Trestní řízení – veřejnost'),
  ('Služební příprava', 'Podle čích pokynů poskytuje justiční stráž ochranu svědkům, jejichž totožnost a podoba má být utajena?', '["Podle pokynů předsedy senátu", "Podle pokynů ředitele", "Podle pokynů vedoucího oddělení VS", "Podle pokynů státního zástupce"]'::jsonb, 0, 'Justiční stráž poskytuje podle pokynů předsedy senátu ochranu svědkům, jejichž totožnost a podoba má být utajena; při ochraně chráněné osoby spolupracuje s policií. (Právní úprava: § 22 odst. 7 zákona č. 555/1992 Sb.; § 140 odst. 2 NGŘ č. 33/2019)', '§ 22 odst. 7 zákona č. 555/1992 Sb.; § 140 odst. 2 NGŘ č. 33/2019', 'Justiční stráž – ochrana svědků'),
  ('Služební příprava', 'Který z uvedených případů je podle § 151 odst. 1 NGŘ č. 33/2019 důvodem ke služebnímu zákroku justiční stráže proti osobě v justičním objektu?', '["Osoba hlasitě telefonuje ve vstupní hale soudu", "Osoba je mu známa jako celostátně hledaná policií", "Osoba odmítá odložit svrchní oděv v šatně", "Osoba odmítá sdělit důvod své návštěvy v budově soudu"]'::jsonb, 1, 'Mezi případy podle § 151 odst. 1 patří mj. ohrožení života či zdraví, hrozící škoda, napadení zaměstnance, prokazatelné narušení pořádku a osoba celostátně nebo mezinárodně hledaná policií. (Právní úprava: § 151 odst. 1 NGŘ č. 33/2019)', '§ 151 odst. 1 NGŘ č. 33/2019', 'Justiční stráž – oprávnění k zákroku'),
  ('Služební příprava', 'Kdo rozhoduje o způsobu přepravy cenin a finanční hotovosti a o počtu příslušníků, kteří ji zajišťují?', '["Ředitel věznice na návrh velitele přepravy", "Vrchní inspektor justiční stráže podle směny", "Statutární zástupce soudu podle výše částky", "Pokladní soudu podle vlastního uvážení"]'::jsonb, 2, 'O způsobu a počtu příslušníků rozhoduje v závislosti na výši přepravované částky a v souladu s instrukcí ministerstva statutární zástupce soudu; přepravu zajišťují zpravidla dva příslušníci. (Právní úprava: § 144 NGŘ č. 33/2019)', '§ 144 NGŘ č. 33/2019', 'Justiční stráž – přeprava cenin'),
  ('Služební příprava', 'Kdo určuje velitele přepravy cenin a finanční hotovosti?', '["Pokladní soudu před výběrem v bance", "VIJS ústním pokynem při rozdílení", "Předseda soudu písemným pověřením pro každou přepravu", "Vedoucí oddělení justiční stráže denním rozkazem"]'::jsonb, 3, 'Velitel přepravy je určen denním rozkazem vedoucího oddělení justiční stráže, kterým se určují i další příslušníci a časový sled úkonu. (Právní úprava: § 127 a § 144 NGŘ č. 33/2019)', '§ 127 a § 144 NGŘ č. 33/2019', 'Justiční stráž – přeprava cenin'),
  ('Služební příprava', 'Kdy nastupují příslušníci justiční stráže do vozidla při přepravě finanční hotovosti?', '["Až když je v něm bezpečně usazena střežená osoba", "Současně se střeženou osobou z obou stran", "Až po nastartování motoru řidičem soudu", "Jako první, aby vozidlo předem zkontrolovali a zajistili"]'::jsonb, 0, 'Příslušníci nastupují do vozidla až tehdy, když je v něm bezpečně usazena střežená osoba (zaměstnanec soudu). (Právní úprava: § 144 NGŘ č. 33/2019; učební text Justiční stráž, s. 15)', '§ 144 NGŘ č. 33/2019; učební text Justiční stráž, s. 15', 'Justiční stráž – přeprava cenin'),
  ('Služební příprava', 'Jak se při pěším doprovodu zajišťovaného zaměstnance dvěma příslušníky rozmístí příslušníci?', '["Oba jdou vedle zaměstnance, každý z jedné jeho strany souběžně", "Jeden jde vedle zaměstnance a velitel přepravy za nimi", "Velitel přepravy vpředu a druhý příslušník vzadu", "Oba jdou těsně za zaměstnancem v zákrytu"]'::jsonb, 1, 'Při zajištění dvěma příslušníky jde jeden příslušník vedle zajišťované osoby a velitel přepravy provádí zajišťování za nimi. (Právní úprava: § 144 odst. 5 a 6 NGŘ č. 33/2019)', '§ 144 odst. 5 a 6 NGŘ č. 33/2019', 'Justiční stráž – přeprava cenin'),
  ('Služební příprava', 'Kde má být při pěším doprovodu neseno zavazadlo s finanční hotovostí?', '["Na zádech zaměstnance v uzavřeném batohu", "Na straně zaměstnance přivrácené k okolí", "Mezi příslušníkem a zajišťovanou osobou", "V rukou velitele přepravy vzadu"]'::jsonb, 2, 'Zavazadlo musí být neseno mezi příslušníkem a zajišťovanou osobou, tedy na straně odvrácené od okolí; nese je výhradně zaměstnanec soudu. (Právní úprava: § 144 NGŘ č. 33/2019; učební text Justiční stráž, s. 15)', '§ 144 NGŘ č. 33/2019; učební text Justiční stráž, s. 15', 'Justiční stráž – přeprava cenin'),
  ('Služební příprava', 'Koho vyrozumí velitel přepravy při neočekávané změně trasy (např. dopravní nehoda)?', '["Krajské operační středisko Policie ČR", "Pobočku banky, z níž se vybírá", "Předsedu soudu přes podatelnu", "VIJS nebo velícího příslušníka"]'::jsonb, 3, 'Příslušníci dodržují stanovené trasy; při neočekávané změně trasy vyrozumí o situaci vrchního inspektora justiční stráže nebo velícího příslušníka. (Právní úprava: § 144 NGŘ č. 33/2019)', '§ 144 NGŘ č. 33/2019', 'Justiční stráž – přeprava cenin'),
  ('Psychologie', 'Jak se nazývá efekt, který je opakem golemovského efektu?', '["Pygmalionský efekt", "Efekt setrvačnosti", "Efekt zakotvení", "Haló efekt (svatozář)"]'::jsonb, 0, 'Golemovský efekt znamená, že řídící pracovník podhodnocuje podřízené a nadhodnocuje sebe; jeho opakem je pygmalionský efekt. (Právní úprava: Učební text Psychologie pro ZOP (2023), kapitola Sociální percepce, s. 18–20)', 'Učební text Psychologie pro ZOP (2023), kapitola Sociální percepce, s. 18–20', 'Sociální percepce'),
  ('Psychologie', 'Co je v sociální percepci „efekt setrvačnosti“?', '["Hodnocení podle jedné nápadné vlastnosti člověka", "Chyba vyplývající z minulých zkušeností s daným člověkem", "Připisování vlastního neúspěchu vnějším podmínkám a okolnostem", "Přeceňování vzhledu hodnocené osoby"]'::jsonb, 1, 'Efekt setrvačnosti je chyba v hodnocení vyplývající z minulých zkušeností s daným člověkem; ostatní možnosti popisují haló efekt, teorii atribuce a estetický stereotyp. (Právní úprava: Učební text Psychologie pro ZOP (2023), kapitola Sociální percepce, s. 18–20)', 'Učební text Psychologie pro ZOP (2023), kapitola Sociální percepce, s. 18–20', 'Sociální percepce'),
  ('Právo', 'Ve kterém ustanovení trestního řádu je upravena zásada legality?', '["§ 2 odst. 13 trestního řádu", "§ 2 odst. 2 trestního řádu", "§ 2 odst. 3 trestního řádu", "§ 2 odst. 8 tr. řádu"]'::jsonb, 2, 'Zásada legality je v § 2 odst. 3 TŘ; odst. 2 upravuje presumpci neviny, odst. 8 zásadu obžalovací a odst. 13 právo na obhajobu. (Právní úprava: § 2 zákona č. 141/1961 Sb.; učební text Právo (2022), s. 66–72)', '§ 2 zákona č. 141/1961 Sb.; učební text Právo (2022), s. 66–72', 'Zásady trestního řízení'),
  ('Zbraně', 'Jaká je kapacita zásobníku pistole CZ 75 B a její plný palebný průměr?', '["15 nábojů, plný palebný průměr 30 nábojů", "12 nábojů, palebný průměr 24 nábojů", "20 nábojů, plný palebný průměr 60 nábojů ve 3 zásobnících", "10 nábojů, plný palebný průměr 20 nábojů"]'::jsonb, 0, 'Pistole CZ 75 B ráže 9 mm Luger má zásobník na 15 nábojů; plný palebný průměr jsou 2 zásobníky po 15 nábojích, tedy 30 nábojů. (Právní úprava: Učební text Speciální příprava – střelecká teorie, s. 3–8)', 'Učební text Speciální příprava – střelecká teorie, s. 3–8', 'Pistole CZ 75'),
  ('Služební příprava', 'Kdy nejpozději informuje příslušník justiční stráže VIJS o průběhu doprovodu zaměstnance soudu při úkonu mimo budovu soudu?', '["Ihned radiostanicí z místa úkonu", "Do 3 pracovních dnů písemnou zprávou", "Nejpozději následující pracovní den", "Až při měsíčním vyhodnocení výkonu služby"]'::jsonb, 2, 'Povinností příslušníka je zajistit bezpečnost a ochranu zaměstnance soudu a po ukončení činnosti informovat VIJS nebo velícího příslušníka o jejím průběhu, nejpozději následující pracovní den. (Právní úprava: § 143 NGŘ č. 33/2019)', '§ 143 NGŘ č. 33/2019', 'Justiční stráž – doprovod'),
  ('Služební příprava', 'Kdo z uvedených je podle § 130 NGŘ č. 33/2019 oprávněn kontrolovat strážní stanoviště justiční stráže?', '["Předseda soudu a jeho místopředsedové", "Obhájce obžalovaného se svolením soudu", "Velitel eskorty vězeňské stráže", "Předseda senátu projednávající věc"]'::jsonb, 0, 'Kontrolu stanovišť justiční stráže mohou vedle funkcionářů ministerstva a VS provádět i předseda příslušného soudu a jeho místopředsedové, vedoucí státní zástupce a další určené osoby; ty při vstupu nepodléhají kontrole. (Právní úprava: § 130 NGŘ č. 33/2019; Instrukce MS č. 8/2022, § 6)', '§ 130 NGŘ č. 33/2019; Instrukce MS č. 8/2022, § 6', 'Kontrola strážní služby'),
  ('Pedagogika', 'Který zákon upravuje výkon ústavní výchovy a ochranné výchovy ve školských zařízeních?', '["Zákon č. 89/2012 Sb.", "Zákon č. 109/2002 Sb.", "Zákon č. 218/2003 Sb.", "Zákon č. 359/1999 Sb. (SPOD)"]'::jsonb, 1, 'Výkon ústavní a ochranné výchovy ve školských zařízeních upravuje zákon č. 109/2002 Sb.; zákon č. 218/2003 Sb. je zákon o soudnictví ve věcech mládeže. (Právní úprava: Učební texty Pedagogika (2023), s. 51–56)', 'Učební texty Pedagogika (2023), s. 51–56', 'Ústavní výchova'),
  ('Pedagogika', 'Pro jaký věk zpravidla zajišťují zařízení ústavní a ochranné výchovy náhradní výchovnou péči?', '["Od narození do 26 let věku", "Od 6 do 15 let věku dítěte", "Od 3 do 18 let, případně do 19 let", "Od 12 do 18 let bez jakékoli výjimky"]'::jsonb, 2, 'Účelem zařízení je zajišťovat nezletilé osobě zpravidla ve věku od 3 do 18 let, případně zletilé osobě do 19 let náhradní výchovnou péči na základě rozhodnutí soudu. (Právní úprava: Učební texty Pedagogika (2023), s. 51–56)', 'Učební texty Pedagogika (2023), s. 51–56', 'Ústavní výchova'),
  ('Právo', 'Kolik trestně odpovědných osob nejméně tvoří organizovanou zločineckou skupinu podle § 129 trestního zákoníku?', '["Nejméně pět osob", "Nejméně deset osob", "Nejméně dvě osoby", "Nejméně tři osoby"]'::jsonb, 3, 'Organizovaná zločinecká skupina je společenství nejméně tří trestně odpovědných osob s vnitřní organizační strukturou, rozdělením funkcí a dělbou činností. (Právní úprava: § 129 zákona č. 40/2009 Sb.)', '§ 129 zákona č. 40/2009 Sb.', 'Trestná součinnost'),
  ('Služební příprava', 'Ve kterém případě se podle § 20 odst. 3 zákona č. 555/1992 Sb. neužije povinnost oznámit použití donucovacího prostředku nadřízenému?', '["Při použití DP při předvádění podle § 17 odst. 4 a 5", "Při použití DP mimo službu proti vězněné osobě", "Při použití DP pod jednotným velením zákroku", "Při použití hmatů a chvatů sebeobrany proti ženě nebo mladistvému"]'::jsonb, 0, 'Oznamovací povinnost se neužije, byl-li donucovací prostředek použit při předvádění podle § 17 odst. 4 a 5; při zákroku pod jednotným velením povinnosti přecházejí na velitele zákroku. (Právní úprava: § 20 odst. 3 a § 21 zákona č. 555/1992 Sb.)', '§ 20 odst. 3 a § 21 zákona č. 555/1992 Sb.', 'Povinnosti po použití DP'),
  ('Služební příprava', 'V kolika výtiscích se zpracovává Záznam o použití donucovacího prostředku?', '["V jednom výtisku", "Ve dvou výtiscích", "Ve třech výtiscích", "Ve čtyřech výtiscích"]'::jsonb, 1, 'Příslušník zpracuje bez zbytečného odkladu Záznam o použití DP na tiskopisu podle PGŘ č. 3/2024 ve dvou výtiscích. (Právní úprava: ML č. 5/2014, § 11; PGŘ č. 3/2024)', 'ML č. 5/2014, § 11; PGŘ č. 3/2024', 'Povinnosti po použití DP'),
  ('Služební příprava', 'Komu se kromě nadřízeného hlásí bez zbytečného odkladu použití donucovacího prostředku proti vězněné osobě?', '["Generální inspekci bezpečnostních sborů ČR", "Předsedovi soudu, který vydal příkaz", "Veřejnému ochránci práv (ombudsmanovi)", "Dozorovému státnímu zástupci krajského SZ"]'::jsonb, 3, 'Použití donucovacího prostředku proti vězněné osobě se hlásí bez zbytečného odkladu dozorovému státnímu zástupci krajského státního zastupitelství. (Právní úprava: ML č. 5/2014, § 11 odst. 3)', 'ML č. 5/2014, § 11 odst. 3', 'Povinnosti po použití DP'),
  ('Služební příprava', 'Kdo musí nařídit, aby písemnost soudu nebo státního zastupitelství doručovala justiční stráž (§ 22 odst. 5 písm. c) zákona č. 555/1992 Sb.)?', '["Předseda senátu nebo státní zástupce", "Ředitel věznice na písemnou žádost soudu", "Adresát písemnosti svou žádostí", "Vedoucí oddělení justiční stráže"]'::jsonb, 0, 'Justiční stráž zajišťuje doručování písemností soudu nebo státního zastupitelství v případě, že tento způsob doručení nařídil předseda senátu nebo státní zástupce. (Právní úprava: § 22 odst. 5 písm. c) zákona č. 555/1992 Sb.; § 146 NGŘ č. 33/2019)', '§ 22 odst. 5 písm. c) zákona č. 555/1992 Sb.; § 146 NGŘ č. 33/2019', 'Justiční stráž – doručování'),
  ('Služební příprava', 'Adresát odepře převzít písemnost doručovanou justiční stráží. Kdy se písemnost považuje za doručenou?', '["Až dnem jejího vrácení soudu", "Dnem, kdy přijetí odepřel", "Po uplynutí lhůty 10 dnů", "Dnem vyvěšení na desce soudu"]'::jsonb, 1, 'Odepře-li adresát písemnost přijmout, považuje se za doručenou dnem odepření; o tom musí být poučen a odepření se vyznačí na doručence. (Právní úprava: § 50c odst. 1 a 3 zákona č. 99/1963 Sb.)', '§ 50c odst. 1 a 3 zákona č. 99/1963 Sb.', 'Justiční stráž – doručování'),
  ('Služební příprava', 'Kde se ukládá písemnost doručovaná justiční stráží v občanském soudním řízení, nebyl-li adresát zastižen?', '["U obecního úřadu v místě bydliště", "Na nejbližší pobočce České pošty", "U okresního soudu, v jehož obvodu je místo doručení", "Na služebně justiční stráže u příslušného krajského soudu"]'::jsonb, 2, 'Písemnost doručovaná justiční stráží se ukládá u okresního soudu, v jehož obvodu je místo doručení; adresátu se zanechá písemná výzva k vyzvednutí. (Právní úprava: § 49 odst. 2 a 3 písm. c) zákona č. 99/1963 Sb.)', '§ 49 odst. 2 a 3 písm. c) zákona č. 99/1963 Sb.', 'Justiční stráž – doručování'),
  ('Služební příprava', 'Smí příslušník justiční stráže při nezastižení adresáta předat písemnost do vlastních rukou dospělému členu jeho domácnosti?', '["Ano, ale jen manželovi nebo registrovanému partnerovi", "Ne, písemnost se vždy ihned vrací odesílajícímu soudu", "Ano, prokáže-li totožnost a podepíše doručenku", "Ne, převzít ji může jen osoba zmocněná plnou mocí"]'::jsonb, 3, 'Náhradní doručení dospělému členu domácnosti platný OSŘ nezná; za adresáta může převzít jen osoba zmocněná písemnou plnou mocí udělenou před provozovatelem poštovních služeb, jinak se písemnost uloží a zanechá výzva. (Právní úprava: § 49 a § 50a odst. 1 zákona č. 99/1963 Sb.)', '§ 49 a § 50a odst. 1 zákona č. 99/1963 Sb.', 'Justiční stráž – doručování'),
  ('Služební příprava', 'Jak se doručuje písemnost v obálce typu III, nebyl-li adresát zastižen?', '["Vhodí se do schránky a je tím doručena", "Vrátí se ihned odesílajícímu soudu bez výzvy", "Předá se sousedovi proti podpisu", "Uloží se na 10 dnů u soudu"]'::jsonb, 0, 'U jiných písemností (obálka III) se písemnost neukládá; nezastihne-li doručující orgán adresáta, vhodí ji do schránky a písemnost je doručena vhozením. (Právní úprava: § 50 odst. 1 zákona č. 99/1963 Sb.)', '§ 50 odst. 1 zákona č. 99/1963 Sb.', 'Justiční stráž – doručování'),
  ('Služební příprava', 'Jaký charakter má doručenka vyplněná doručujícím orgánem?', '["Jde o soukromou listinu doručovatele", "Jde o veřejnou listinu podle zákona", "Jde jen o interní evidenční doklad", "Jde o podklad bez důkazní hodnoty"]'::jsonb, 1, 'Doručenka je veřejnou listinou; doručovatel na ní vyznačuje mj. den nezastižení, den připravení k vyzvednutí, odepření přijetí a připojuje jméno, podpis a otisk razítka. (Právní úprava: § 50f odst. 3 a § 50g zákona č. 99/1963 Sb.)', '§ 50f odst. 3 a § 50g zákona č. 99/1963 Sb.', 'Justiční stráž – doručování'),
  ('Psychologie', 'Jak se nazývá asertivní technika spočívající v klidném opakování toho, co chceme, bez reakce na manipulativní manévry partnera?', '["Selektivní ignorování", "Negativní dotazování partnera", "Technika otevřených dveří", "Pokažená gramofonová deska"]'::jsonb, 3, 'Pokažená gramofonová deska je klidné opakování požadavku bez rozvíjení vedlejších témat; otevřené dveře znamenají klidné připuštění kritiky, negativní aserce souhlas s kritikou vlastních chyb. (Právní úprava: Učební text Psychologie pro ZOP (2023), Asertivní techniky, s. 20–23)', 'Učební text Psychologie pro ZOP (2023), Asertivní techniky, s. 20–23', 'Asertivní techniky'),
  ('Psychologie', 'Co znamená asertivní technika „selektivní ignorování“?', '["Nereagovat na nevěcnou kritiku, jen dát najevo, že jsme slyšeli", "Nabízení nevyžádaných informací o sobě pro usnadnění dalšího rozhovoru", "Aktivní podpora kritiky dotazem, co ještě partnerovi vadí", "Souhlas s kritikou vlastních skutečných chyb bez omlouvání"]'::jsonb, 0, 'Selektivní ignorování znamená na manipulativní, nevěcnou nebo obecnou kritiku nereagovat, jen dát najevo, že jsme slyšeli; ostatní možnosti popisují negativní aserci, volné informace a negativní dotazování. (Právní úprava: Učební text Psychologie pro ZOP (2023), Asertivní techniky, s. 20–23)', 'Učební text Psychologie pro ZOP (2023), Asertivní techniky, s. 20–23', 'Asertivní techniky'),
  ('Právo', 'U kterých trestných činů je trestný pokus podle § 21 trestního zákoníku?', '["Jen u zvlášť závažných zločinů", "U všech úmyslných trestných činů", "Jen stanoví-li to trestní zákon výslovně", "U úmyslných i nedbalostních činů"]'::jsonb, 1, 'Pokus je trestný u všech úmyslných trestných činů podle sazby na dokonaný čin; příprava je trestná jen u zvlášť závažných zločinů a jen stanoví-li to zákon výslovně. (Právní úprava: § 20 a § 21 zákona č. 40/2009 Sb.)', '§ 20 a § 21 zákona č. 40/2009 Sb.', 'Vývojová stadia trestného činu'),
  ('Penologie', 'V jakém rozsahu lze odsouzenému uložit kázeňský trest snížení kapesného?', '["Nejvýše o polovinu až na 6 měsíců", "Nejvýše o jednu třetinu až na 3 kalendářní měsíce", "Nejvýše o čtvrtinu až na 1 kalendářní měsíc", "Odnětí celého kapesného až na dobu 2 kalendářních měsíců"]'::jsonb, 1, 'Podle § 46 odst. 3 lze uložit snížení kapesného nejvýše o jednu třetinu až na dobu 3 kalendářních měsíců. (Právní úprava: § 46 odst. 3 zákona č. 169/1999 Sb.)', '§ 46 odst. 3 zákona č. 169/1999 Sb.', 'Kázeňské tresty'),
  ('Penologie', 'Na jak dlouho lze obviněnému uložit kázeňský trest zákazu nákupu potravin a věcí osobní potřeby (s výjimkou hygienických potřeb)?', '["Až na dobu tří měsíců", "Až na dobu 14 dnů", "Až na dobu 1 týdne", "Až na dobu 1 měsíce"]'::jsonb, 3, 'Obviněnému lze uložit zákaz nákupu až na dobu jednoho měsíce; u mladistvých obviněných nesmí tento zákaz přesáhnout jeden týden. (Právní úprava: § 22 odst. 2 a § 26 odst. 3 zákona č. 293/1993 Sb.)', '§ 22 odst. 2 a § 26 odst. 3 zákona č. 293/1993 Sb.', 'Kázeňské tresty obviněných'),
  ('Penologie', 'Do kdy musí být rozhodnuto o uložení kázeňského trestu obviněnému a rozhodnutí oznámeno?', '["Do 15 dnů od zjištění, nejpozději do 1 měsíce od porušení", "Do 1 měsíce od zjištění, nejpozději do 1 roku od jeho porušení", "Do 8 dnů od zjištění, nejpozději do 6 měsíců", "Do 3 dnů od zjištění, nejpozději do 15 dnů od porušení"]'::jsonb, 0, 'O kázeňském trestu obviněnému musí být rozhodnuto a rozhodnutí oznámeno do 15 dnů ode dne, kdy se oprávněný orgán o přestupku dozvěděl, nejpozději do jednoho měsíce od porušení pořádku a kázně. (Právní úprava: § 23 odst. 3 zákona č. 293/1993 Sb.)', '§ 23 odst. 3 zákona č. 293/1993 Sb.', 'Kázeňské tresty obviněných'),
  ('Penologie', 'V jaké lhůtě může obviněný podat stížnost proti rozhodnutí o kázeňském trestu a do kdy se o ní rozhoduje?', '["Do 8 dnů, rozhoduje se do 15 dnů", "Do 3 dnů, rozhoduje se do 5 pracovních dnů", "Do 24 hodin, rozhoduje se ihned", "Do 15 dnů, rozhoduje se do 30 kalendářních dnů"]'::jsonb, 1, 'Stížnost lze podat do 3 dnů a rozhoduje se o ní do 5 pracovních dnů. (Právní úprava: § 23 odst. 6 a 7 zákona č. 293/1993 Sb.)', '§ 23 odst. 6 a 7 zákona č. 293/1993 Sb.', 'Kázeňské tresty obviněných'),
  ('Penologie', 'Jak často má nárok na návštěvu mladistvý obviněný?', '["Dvakrát týdně", "Jednou za 2 týdny", "Jednou za týden", "Jednou za měsíc"]'::jsonb, 2, 'Obviněný má nárok na návštěvu jednou za 2 týdny v délce 90 minut, mladistvý obviněný jednou za týden. (Právní úprava: § 14 a § 26 odst. 2 zákona č. 293/1993 Sb.)', '§ 14 a § 26 odst. 2 zákona č. 293/1993 Sb.', 'Návštěvy obviněných'),
  ('Právo', 'V jaké lhůtě a ke kterému soudu se podává dovolání v trestním řízení?', '["Do 8 dnů ke krajskému soudu", "Do 2 měsíců k Nejvyššímu soudu", "Do 3 dnů k příslušnému vrchnímu soudu", "Do 6 měsíců k Ústavnímu soudu"]'::jsonb, 1, 'Dovolání se podává do 2 měsíců k Nejvyššímu soudu; odvolání a odpor mají lhůtu 8 dnů, stížnost 3 dny. (Právní úprava: § 265e zákona č. 141/1961 Sb.)', '§ 265e zákona č. 141/1961 Sb.', 'Opravné prostředky'),
  ('Služební příprava', 'Na jaké kategorie se podle NGŘ č. 16/2022 dělí mimořádné události?', '["Na hlášené a nehlášené mimořádné události", "Na události I., II. a III. kategorie", "Na závažné a ostatní mimořádné události", "Na vnitřní, vnější a smíšené události"]'::jsonb, 2, 'Mimořádné události podle NGŘ č. 16/2022 se dělí na závažné a ostatní; žádná „I. kategorie“ neexistuje. (Právní úprava: NGŘ č. 16/2022, § 4 až 6)', 'NGŘ č. 16/2022, § 4 až 6', 'Mimořádné události')
